(window.AQIDA_TEXTS = window.AQIDA_TEXTS || {})["493"] = {"atoms": {"493.1": {"x": [[3, "هُوَ الَّذِي أَنْزَلَ عَلَيْكَ الْكِتَابَ مِنْهُ آيَاتٌ مُحْكَمَاتٌ هُنَّ أُمُّ الْكِتَابِ وَأُخَرُ مُتَشَابِهَاتٌ فَأَمَّا الَّذِيْنَ فِيْ قُلُوبِهِمْ زَيْغٌ فَيَتَّبِعُوْنَ مَا تَشَابَهَ مِنْهُ ابْتِغَاءَ الْفِتْنَةِ وَابْتِغَاءَ تَأْوِيْلِهِ وَمَا يَعْلَمُ تَأْوِيْلَهُ إِلَّا اللهُ وَالرَّاسِخُوْنَ فِي الْعِلْمِ يَقُوْلُوْنَ آمَنَّا بِهِ} [آل عمران: 7].\rالحمد لله الذي هدانا صراطًا مستقيمًا بالإقرار الخالي عن التشبيه والتعطيل والصلاة والسلام على سيدنا محمد الذي نهى عن عبادة الأصنام والتماثيل.\rأما بعد فهذا كتاب لابن الجوزي حجبه عنا هذه البرهة - بل عن كثير من المتخصصين في معرفة المؤلفات العربية - فئة من أشياع الذين رد عليهم المصنف عملت على محو اسمه ورسمه؛ قد حملني على طبعه انتشار كتب المشبهة - مخطوطها ومطبوعها - في الناس، واشتغال بعض المؤلفين بالدعوة إلى التشبيه حتى اليوم والحرص على نشر تصانيف ابن الجوزي النافعة وكتب الردود الماتعة.\rوقد علق عليه الأستاذ الشيخ محمد زاهد الكوثري - نزيل القاهرة - أدام الله النفع به."], [4, "[المقدمة]\r"]], "pg": [3, 4]}, "493.2": {"x": [[4, "قال الشيخ الإمام الحافظ العلامة أبو الفرج عبد الرحمن بن علي الجوزي الصديقي البكري:\rاعلم وفقك الله تعالى أني لما تتبعت مذهب الإمام أحمد رحمه الله تعالى رأيته رجلا كبير القدر في العلوم، قد بالغ رحمة الله عليه في النظر في علوم الفقه ومذاهب القدماء، حتى لا تأتي مسألة إلا وله فيها نص أو تنبيه إلا أنه على طريق السلف، فلم يصنف إلا المنقول، فرأيت مذهبه خاليا من التصانيف التي كثر جنسها عند الخصوم. فصنفت تفاسير مطولة منها «المغني» مجلدات و «زاد المسير»، و «تذكرة الاريب» وغير ذلك.\rوفي الحديث: كتبا منها «جامع المسانيد»، و «الحدائق»، و «نفي النقل»، وكتبا كثيرة في الجرح والتعديل.\rوما رأيت لهم «تعليقة» في الخلاف إلا أن القاضي «أبا يعلى» قال: كنت أقول ما لاهل المذاهب يذكرون الخلاف مع خصومهم ولا يذكرون أحمد (1) ثم عذرتهم، إذ ليس لنا تعليقة في\r__________\r(1) كان الإمام أحمد رضي الله عنه لزم الإمام يوسف في بدء أمره، كما حكى ذلك عنه يحيى بن معين حيث يقول في كتابه - معرفة التاريخ والعلل (رواية أبي العباس الأصم عن أبي الفضل العباس بن محمد الدوري عنه) -: سمعت أحمد بن حنبل يقول: اختلفت إلى أبي يوسف ثم اختلفت إلى الناس بعده أهـ. وكان يشتغل بكتب محمد بن الحسن ويستفيد منها أجوبة دقيقة، على ما رواه الخطيب بإسناده إلى الحربي عنه، وصحب كثيرا من فقهاء العراق، وجالس الشافعي في قدمته الثانية ببغداد بعد وفاة محمد، فصار له من الفقه حظ وافر، ومع هذا كله كان الغالب عليه وعلى أصحابه رواية الحديث، ولم ="], [5, "الفقه، قال: فصنفت لهم تعليقة.\rقلت: وتعليقته لم يحقق فيها بيان الصحة والطعن في المردود، وذكر فيها أقيسة طردية. ورأيت من يلقي الدرس من أصحابنا من يفزع إلى تعليقة الاصطلام أو تعليقة أسعد، أو تعليقة العاملي، أو تعليقة الشريفة ويستعير منها استعارات. فصنفت لهم تعاليق منها «كتاب الأنصاف في مسائل الخلاف» ومنها «جنة النظر وجنة الفطر» ومنها «عمدة الدلائل في مشهور المسائل».\rثم رأيت جمع أحاديث التعليق التي يحتج بها أهل المذاهب، وبينت تصحيح الصحيح، وطعن المطعون فيه وعملت كتابا في المذاهب أدخلتها فيه، وسميته «الباز الاشهب المنقض على مخالفي المذهب».\r__________\r= يكن يجرى على طريقة الفقهاء في التفريع - والتأصيل وتبيين مناط الأحكام والتعليل، حتى قلت انفراداته في الفروع عمن تقدمه من الفقهاء، فإن خالف الشافعي مثلا في شيء من قوله الجديد تراه يوافق فيه أبا حنيفة أو أحد أصحابه أو مالكا رضي الله عنهم، فكان يستغني أصحاب كتب الخلاف عن ذكر أقوال أحمد بذكر خلاف من تقدمه من الفقهاء، ولم يذع تدوين أقواله مع أقوال بقية الفقهاء في كتب الخلاف إلا في عهد ابن هبيرة الوزير فإنه لما ألف إفصاحه وخص من بين مجلداته مجلدا ضخما باختلاف الأئمة الأربعة، واعتنى به عناية تامة وسعى في نشره بصرف مبالغ طائلة، أخذ من يكتب في الخلاف يذكر أقوال أحمد مع أقوال غيره من الأئمة، وكان ابن جرير أدركه سنا وأدرك أصحابه لقاء ومع ذلك لم يذكر أقواله فيما كتبه في اختلاف الفقهاء مع ذكره من هو على شاكلة أبي بكر عبد الرحمن بن كيسان الأصم، فسأله الحنابلة عن ذلك فقال ما معناه: لم يكن أحمد من الفقهاء وإنما كان من أهل الحديث وما كنت لقيته حتى آخذ منه ولا لقيت أصحابا له يحق أن يؤخذ منهم فثارت ثائرة الحنابلة عليه وجرى ما ينقله ياقوت في معجم الأدباء وابن الأثير في كامله. (ز)."], [6, "وصنفت في الفروع كتاب «المذهب في المذهب» وكتاب «مسبوك الذهب» وكتاب «البلغة» وكتاب «منهاج الوصول إلى علم الاصول» وقد بلغت مصنفاتي مائتين وخمسين مصنفا.\rورأيت من أصحابنا من تكلم في الاصول بما لا يصلح، وانتدب للتصنيف ثلاثة: أبو عبد الله بن حامد (1). وصاحبه القاضي (2)، وابن الزاغوني (3) فصنفوا كتبا شانوا بها المذهب، ورأيتهم قد نزلوا إلى مرتبة العوام، فحملوا الصفات على مقتضى الحس. فسمعوا أن الله تعالى خلق آدم على صورته، فأثبتوا له صورة ووجها زائدا على الذات، وعينين،\r__________\r(1) هو شيخ الحنابلة أبو عبد الله الحسن بن حامد بن على البغدادي الوراق المتوفى سنة ثلاث وأربعمائة، وكان من أكبر مصنفيهم، له شرح أصول الدين، فيه طامات سيورد المصنف بعضها، ولديه تخرج القاضي أو يعلى الحنبلي. (ز).\r(2) هو القاضي أبو يعلى محمد بن الحسين بن محمد بن خلف بن الفراء الحنبلي المتوفى سنة ثمان وخمسين وأربعمائة، وفيه يقول أبو محمد التميمي ما معناه: لقد شان أبو يعلى الحنابلة شيئا لا يغسله ماء البحار، على ما نقله ابن الأثير وأبو الفداء، وعزا في طبقاته إلى الإمام أحمد ما يبعد أن يصح عنه كل البعد، ونقل ابن بدران الدشتي في جزء إثبات الحد عن كتاب الأصول لأبي يعلي هذا ما هو أفظع مما سينقله المصنف عنه في التشبيه، على تضارب في أقواله بين تنزيه وتشبيه، ولا يخفى على الناظر أن غير الحافظ أبي يعلى أحمد ابن على الموصلي صاحب المسند وراوي كتب أبي يوسف عن بشر بن الوليد. (ز)\r(3) هو أبو الحسن على بن عبيد الله بن نصر الزاغوني الحنبلي المتوفى سنة سبع وعشرين وخمسمائة، وهو من مشايخ المصنف، وله في كتاب الإيضاح من غرائب التشبيه ما يحار فيه النبيه. (ز)"], [7, "وفمًا ولهوات وأضراسا وأضواء لوجهه هي السبحات ويدين، وأصابع وكفا وخنصرا وإبهاما وصدرا وفخذا وساقين ورجلين. وقالوا: ما سمعنا بذكر الرأس.\rوقالوا: يجوز أن يمس ويمس، ويدني العبد من ذاته. وقال بعضهم: ويتنفس. ثم يرضون العوام بقولهم: «لا كما يعقل».\rوقد أخذوا بالظاهر في الاسماء والصفات، فسموها بالصفات تسمية مبتدعة لا دليل لهم في ذلك من النقل ولا من العقل، ولم يلتفتوا إلى النصوص الصارفة عن الظواهر إلى المعاني الواجبة لله تعالى ولا إلى إلغاء ما يوجبه الظاهر من سمات الحدوث، ولم يقنعوا بأن يقولوا صفة فعل، حتى قالوا صفة ذات.\rثم لما أثبتوا أنها صفات ذات قالوا: لا نحملها على توجيه اللغة مثل يد على نعمة وقدرة، ومجئ وإتيان على معنى بر ولطف، وساق على شدة، بل قالوا: نحملها على ظواهرها المتعارفة والظاهر هو المعهود من نعوت الآدميين، والشيء إنما يحمل على حقيقته إذا أمكن، ثم يتحرجون من التشبيه ويأنفون من إضافته إليهم ويقولون: نحن أهل السنة، وكلامهم صريح في التشبيه.\rوقد تبعهم خلق من العوام. فقد نصحت التابع والمتبوع فقلت لهم: يا أصحابنا أنتم أصحاب نقل وإمامكم الاكبر"], [8, "أحمد بن حنبل يقول وهو تحت السياط: كيف أقول ما لم يقل (1). فإياكم أن تبتدعوا في مذهبه ما ليس منه، ثم قلتم في الاحاديث، تحمل على ظاهرها. وظاهر القدم الجارحة، فإنه لما قيل في عيسى روح الله اعتقدت النصارى أن لله صفة هي روح ولجت في مريم.\rومن قال: استوى بذاته فقد أجراه مجرى الحسيات، وينبغى أن لا يهمل ما يثبت به الاصل وهو العقل، فإنا به عرفنا الله تعالى، وحكمنا له بالقدم، فلو أنكم قلتم: نقرأ الاحاديث ونسكت، ما أنكر عليكم أحد، إنما حملكم إياها على الظاهر قبيح (2).\r__________\r(1) ولما سئل الإمام أحمد عن أحاديث النزول والرؤية وضع القدم ونحوها قال: «نؤمن بها ونصدق بها ولا كيف ولا معنى»، وقال أيضا يوم سألوه عن الاستواء: «استوى على العرش كيف شاء وكما شاء بلا حد ولا صفة يبلغها واصف» على ما ذكره الخلال في السنة بسنده إلى حنبل عن عمه الإمام أحمد، وهذا تفويض وتنزيه كما هو مذهب السلف، وربما أول في بعض المواضع كما حكى حنبل أيضا عن الإمام أحمد أنه سمعه يقول: احتجوا على يوم المناظرة فقالوا: تجيئ يوم القيامة سورة البقرة وتجيئ سورة تبارك، قال فقلت لهم: إنما هو الثواب قال الله جل ذكره {وَجَاءَ رَبُّكَ وَالْمَلَكُ صَفًّا صَفًّا} [الفجر: 22] وإنما تأتي قدرته. وقال ابن حزم الظاهري في فصله: وقد روينا عن أحمد بن حنبل رحمه الله أنه قال: «وجاء ربك» إنما معناه: وجاء أمر ربك اهـ. وهذا تأويل وتنزيه كما هو مذهب الخلف، وأما ما ينقلعن الإمام أحمد مما يخالف ما تقدم فهو تخرص صديق جاهل وسوء فهم لمذهب هذا الإمام. (ز)\r(2) يقول الأستاذ الشيخ محمد عبده رحمه الله فيما كتبه على العضدية عند الكلام على حديث افتراق الأمة: فإن قلت: إن كلام الله وكلام النبي صلى الله عليه وسلم مؤلف من الألفاظ العربية ومدلولاتها معلومة لدى أهل اللغة فيجب الأخذ يحاق مدلول اللفظ كان ما كان: قلت: ="], [9, "فلا تدخلوا في مذهب هذا الرجل الصالح السلفي ما ليس منه. ولقد كسيتم هذا المذهب شينا قبيحا حتى صار لا يقال حنبلي إلا مجسم، ثم زينتم مذهبكم أيضا بالعصبية ليزيد بن معاوية ولقد علمتم أن صاحب المذهب أجاز لعنته، وقد كان أبو محمد التميمي يقول في بعض أئمتكم (1): لقد شان المذهب شينا قبيحا لا يغسل إلى يوم القيامة.\r***\r\r[فصل: في الأغلاط التي وقع فيها المردود عليهم]\r"]], "pg": [4, 9]}, "493.3": {"x": [[9, "فصل: وقد وقع غلط المصنفين الذين ذكرتهم في سبعة أوجه:\rأولها: أنهم سموا الاخبار أخبار صفات، وإنما هي إضافات، وليس كل مضاف صفة، فإنه قال سبحانه وتعالى: {وَنَفَخْتُ فِيهِ مِنْ رُوحِي} [الحجر: 29]. وليس لله صفة تسمى روحا، فقد ابتدع من سمى المضاف صفة.\rوالثاني: أنهم قالوا: إن هذه الاحاديث من المتشابه الذي لا يعلمه إلا الله تعالى. ثم قالوا: نحملها على ظواهرها، فواعجبا!! ما لا يعلمه إلا الله أي ظاهر له. .؟! فهل ظاهر الاستواء إلا القعود، وظاهر\r__________\r=حينئذ لم يكن ناجيا إلا طائفة المجسمة الظاهريون القائلون بوجوب الأخذ بجميع النصوص وترك طريق الاستدلال رأسا، مع أنه لا يخفى ما في آراء هذه الطائفة من الاختلال، مع سلوكهم طريقا ليس يفيد اليقين بوجه، فإن للتخاطبات مناسبات ترد بمطابقتها فلا سبيل إلا إلى الاستدلال وتأويل ما يبدى بظاهره نقصا إلى ما يفيد الكمال، وإذا صح التأويل للبرهان في شيء صح في بقية الأشياء حيث لا فرق بين برهان وبرهان ولا لفظ ولفظ. (ز)\r(1) وهو القاضي أبو يعلى المتقدم. (ز)"], [10, "النزول إلا الأنتقال!.\rوالثالث: أنهم أثبتوا لله تعالى صفات، وصفات الحق جل جلاله لا تثبت إلا بما يثبت به الذات من الادلة القطعية.\rوالرابع: أنهم لم يفرقوا في الاحاديث بين خبر مشهور كقوله: «ينزل إلى السماء الدنيا» وبين حديث لا يصح كقوله: «رأيت ربي في أحسن صورة» بل أثبتوا بهذا صفة وبهذا صفة.\rوالخامس: أنهم لم يفرقوا بين حديث مرفوع إلى النبي صلى الله عليه وسلم وبين حديث موقوف على صحابي أو تابعي، فأثبتوا بهذا ما أثبتوا بهذا.\rوالسادس: أنهم تأولوا بعض الالفاظ في موضع ولم يتأولوها في موضع آخر كقوله: «من أتاني يمشي أتيته هرولة». قالوا: هذا ضرب مثل للأنعام.\rالسابع: أنهم حملوا الاحاديث على مقتضى الحس فقالوا: ينزل بذاته، وينتقل ويتحرك، ثم قالوا: لا كما يعقل. فغالطوا من يسمع فكابروا الحس والعقل فحملوا الاحاديث على الحسيات.\rفرأيت الرد عليهم لازما لئلا يتسب الإمام إلى ذلك، وإذا سكت نسبت إلى اعتقاد ذلك، ولا يهولني أمر عظيم في النفوس لأن العمل على الدليل، وخصوصًا في معرفة الحق تعالى"], [11, "لا يجوز فيه التقليد، وقد سئل الإمام أحمد عن مسألة فأفتى فيها فقيل له: هذا لا يقول به ابن المبارك، فقال: ابن المبارك لم ينزل من السماء، وقال الإمام الشافعي رحمه الله تعالى: استخرت الله تعالى في الرد على الإمام مالك رحمه الله.\rولما صنف هؤلاء الثلاث كتبا، وانفرد القاضي أبو يعلي فصنف الاحاديث التي ذكرتها على ترتيبه، وقدم عليها الآيات الشريفة التي وردت في ذلك."], [12, "[باب: ما جاء في القرآن العظيم من آيات الصفات]\r"]], "pg": [9, 12]}, "493.4": {"x": [[12, "باب ما جاء في القرآن العظيم من ذلك\rقال الله تعالى: {وَيَبْقَى وَجْهُ رَبِّكَ ذُو الْجَلَالِ وَالْإِكْرَامِ} (1) [الرحمن: 27]. قال المفسرون: معناه يبقى ربك، وكذا قالوا في قوله تعالى: {يُرِيْدُوْنَ وَجْهَهُ} [الأنعام: 52] أي يريدونه. وقال الضحاك وأبو عبيدة في قوله: {كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ} [القصص: 88] أي إلا هو.\rوقد ذهب الذين أنكرنا عليهم إلى أن الوجه صفة تختص باسم زائد على الذات. قلت: فمن أين قالوا هذا وليس لهم دليل إلا ما عرفوه من الحسيات. . .؟ وذلك يوجب التبعيض، ولو كان كما قالوا: كان المعنى: أن ذاته تهلك إلا وجهه. وقال ابن حامد: أثبتنا لله وجها ولا نجوز إثبات رأس. قلت: ولقد اقشعر بدني من جراءته على ذكر هذا فما أعوزه في التشببه غير الرأس.\rومنها قوله تعالى: {وَلِتُصْنَعَ عَلَى عَيْنِيْ} [طه: 39]، {وَاصْنَعِ الْفُلْكَ بِأَعْيُنِنَا} (2) [هود: 37]. أي بمرأى منا، وإنما جمع لأن عادة الملك أن يقول: أمرنا ونهينا.\r__________\r(1) قال الزمخشري في الكشاف: {وَجْهُ رَبِّكَ} [الرحمن: 55] ذاته، والوجه يعبر به عن الجملة والذات، ومساكين مكة يقولون: أين وجه عربي كريم ينقذني من الهوان.\r(2) يقول الزمخشري: {بِأَعْيُنِنَا} [هود: 37] في موضع الحال بمعنى اصنعها محفوظا وحقيقته ملتبسا بأعيننا كأن لله معه أعينا تكلؤه أن يزيغ في صنعته عن الصواب وأن لا يحول بينه وبين عمله أحد من أعدائه. ه ويقول الرازي في أساس التقديس عند الكلام على العين: لا بد من المصير إلى التأويل وذلك هو أن يحمل هذه الألفاظ على شدة العناية والحراسة، والوجه في حسن هذا المجاز أن من عظمت عنايته بشيء وميله إليه ورغبته فيه كان كثير النظر إليه فجعل لفظ العين التي هي آلة لذلك النظر كناية عن شدة العناية."], [13, "[الحافظ أبو بكر بن خزيمه وإنه ممن سقطوا في هوة التشبيه]\r"]], "pg": [12, 13]}, "493.5": {"x": [[13, "وقد ذهب القاضي «أبو يعلى» إلى أن العين صفة زائدة على الذات وقد سبقه أبو بكر بن خزيمة (1) فقال في الآية: «لربنا عينان ينظر بهما، وقال ابن حامد: يجب الإيمان أن له عينين.\rوهذا ابتداع لا دليل لهم عليه وإنما أثبتوا عينين من دليل الخطاب في قوله عليه الصلاة والسلام: «وان الله ليس بأعور» (2). وإنما أريد نفي النقص عنه تعالى، ومتى ثبت أنه لا يتجزأ لم يكن لما يتخايل من الصفات وجه.\rومنها قوله تعالى: {لِمَا خَلَقْتُ بِيَدَيَّ} [ص: 75] (3) اليد في اللغة:\r__________\r(1) هو محمد بن إسحاق بن خزيمة النيسابوري توفى عام أحمد عشر وثلثمائة، يعد في أكابر المحدثين، كان يورع نفسه عن الخوض في مسائل الكلام وينهى أصحابه عنه، ثم اضطره بعض أهل النظر إلى الدخول في هذه المآزم فزلت قدمه وخرج إلى وجوه غير معقولة سامحه الله. (ز)\r(2) طالع الحديث الخمسين الآتي ترى مزيد تفصيل عن هذا الخبر.\r(3) يقول الزمخشري: أن ذا اليدين يباشر أكثر أعماله بيديه، فغلب العمل باليدين على سائر الأعمال التي تباشر بغيرهما، حتى قيل في عمل القلب: هو مما عملت يداك، وحتى قيل لمن لا يدى له: يداك أو كتا وفوك نفخ، وحتى لم يبق فرق بين قولك: هذا مما عملته وهذا مما عملته يداك ا. ه وقال الراغب الأصبهاني في مفرداته: قوله تعالى {مِمَّا عَمِلَتْ أَيْدِيْنَا} [يس: 71] وقوله {لِمَا خَلَقْتُ بِيَدَيَّ} [ص: 75] عبارة عن توليه لخلقه باختراعه الذي ليس إلا له عز وجل، وخص لفظ اليد ليتصور لنا المعنى إذ هو أجل الجوارح التي يتولى بها الفعل فيما بيننا ليتصور لنا اختصاص المعنى لا لنتصور منه تشبيها، وقيل معناه بنعمتي التي رشحتها لهم، والباء فيه ليس كالباء في قولهم: قطعته بالسكين بل هو كقولهم: خرج بسيفه أي معه سيفه، معناه خلقته ومعه نعتاي الدنيوية والأخروية اللتان إذا رعاهما بلغ بهما السعادة الكبرى.\rوقال العلامة الشيخ جمال الدين القاسمي في تفسيره محاسن التأويل: {لِمَا خَلَقْتُ بِيَدَيَّ} [ص: 75] أي بنفسي من غير توسط كأب وأم."], [14, "بمعنى النعمة والاحسان، ومعنى قول اليهود لعنهم الله تعالى: {يَدُ اللهِ مَغْلُوْلَةٌ} [المائدة: 64] أي: محبوسة عن النفقة، واليد: القوة، يقولون: ما لنا بهذا الامر من يد.\rوقوله: {بَلْ يَدَاهُ مَبْسُوْطَتَانِ} [المائدة: 64] أي نعمته وقدرته (1). وقوله: {لِمَا خَلَقْتُ بِيَدَيَّ} [ص: 75] أي بقدرتي ونعمتي، وقال الحسن في قوله تعالى: {يَدُ اللهِ فَوْقَ أَيْدِيهِمْ} [الفتح: 10] أي: منته وإحسانه.\rوقال القاضي «أبو يعلى»: «اليدان صفتان ذاتيتان تسميان باليدين» اهـ. وهذا تصرف بالرأي لا دليل عليه، وقال: لو لم يكن لآدم عليه السلام مزية على سائر الحيوانات بخلقه باليد التي هي صفة لما عظمه بذكرها وأجله فقال (بيدي). ولو كانت القدرة لما كانت له مزية، فإن قالوا القدرة لا تثن.\rقلنا: بلى قالت العرب: ليس لي بهذا الامر يدان، أي ليس لي به قدرة، وقال عروة بن حزام في شعره:\rفقالا شفاك الله والله مالنا ... بما ضمنت منك الضلوع يدان\rوقولهم: ميزه بذلك عن الحيوان، فقد قال تعالى: {خَلَقْنَا لَهُمْ مِمَّا عَمِلَتْ أَيْدِينَا أَنْعَامًا} [يس: 71] ولم يدل هذا على تمييز الأنعام على بقية\r__________\r(1) في أساس التقديس لمجدد القرن السادس الفخر الرازي: والسبب في حسن هذا المجاز أن كمال حال هذا العضو إنما يظهر بالصفة المساة بالقدرة فلما كان المقصود من اليد حصول القدرة أطلق اسم القدرة على اليد، ولأن آلة إعطاء النعمة اليد فإطلاق اسم اليد على النعمة إطلاق لاسم السبب على المسبب."], [15, "الحيوان.\rقال الله تعالى: {وَالسَّمَاءَ بَنَيْنَاهَا بِأَيْدٍ} [الذاريات: 47] أي بقوة ثم قد أخبر أنه نفخ فيه من روحه ولم يرد إلا الوضع بالفعل والتكوين، والمعنى: نفخت أنا، ويكفي شرف الاضافة، إذ لا يليق بالخالق جل جلاله سوى ذلك لأنه لا يحتاج أن يفعل بواسطة، فلا له أعضاء وجوارح يفعل بها، لأنه تعالى الغني بذاته، فلا ينبغي أن يتشاغل بطلب تعظيم آدم مع الغفلة عما يستحقه الباري سبحانه من التعظيم بنفي الابعاض والآلآت في الافعال، لأن هذه الاشياء صفة الاجسام.\rوقد ظن بعض الثلاثة أن الله تعالى يمس، حتى توهموا أن الله تعالى مس طينة آدم بيد هي بعض ذاته، وما فطنوا أنه من جملة مخلوقاته جسما يقابل جسما فيتحد به ويفعل فيه، ومن السحر من يعقد عقدا فيتغير به الشيء حالا وصفة!! أفتراه سبحانه جعل أفعال الاشخاص والاجسام تتعدى إلى الاجسام البعيدة، ثم يحتاج هو في أفعاله إلى معاناة الطين. وقد رد قول من قال هذا بقوله تعالى: {إِنَّ مَثَلَ عِيْسَى عِنْدَ اللهِ كَمَثَلِ آدَمَ خَلَقَهُ مِنْ تُرَابٍ ثُمَّ قَالَ لَهُ كُنْ فَيَكُوْنُ} [آل عمران: 59].\rومنها قوله تعالى: {وَيُحَذِّرُكُمُ اللهُ نَفْسَهُ} [آل عمران: 28] وقوله تعالى: {تَعْلَمُ مَا فِيْ نَفْسِيْ وَلَا أَعْلَمُ مَا فِي نَفْسِكَ} [المائدة: 116] قال المفسرون: ويحذركم الله إياه، وقالوا: «تعلم ما عندي ولا أعلم ما عندك». وقال"], [16, "المحققون: المراد بالنفس هاهنا الذات، ونفس الشيء ذاته.\rوقد ذهب القاضي «أبو يعلى» إلى أن لله نفسا، وهي صفة زائدة على ذاته. قلت: وقوله هذا لا يستند إلا إلى التشبيه، لأنه يوجب أن الذات شيء والنفس غيرها.\rومنها قوله تعالى: {لَيْسَ كَمِثْلِهِ شَيْءٌ} [الشورى: 11] (1). ظاهر الكلام أن له مثلا، فليس كمثله شيء، وليس كذلك، وإنما معناه عند أهل اللغة: أن يقام المثل مقام الشيء نفسه. يقول الرجل: مثلي لا يكلم مثلك، وإنما المعنى: ليس كهو شيء.\rومنها قوله تعالى: {يَوْمَ يُكْشَفُ عَنْ سَاقٍ} [القلم: 42] (2). قال جمهور\r__________\r(1) يقول الزمخشري في الكشاف: قالوا مثلك لا يبخل فنفوا البخل عن مثله وهم يريدون نفيه عن ذاته قصدوا المبالغة في ذلك فسلكوا به طريق الكناية لأنهم إذا نفوه عمن يسد مسده وعمن هو على أخص أوصافه فقد نفوه عنه، ونظيره: قولك للعربي العرب لا تخفر الذمم كان أبلغ من قولك: أنت لا تخفر ومنه قولهم: قد أيفعت لداته وبلغت أترابه يريدون إيفاعه وبلوغه اهـ.\rوقال الراغب: أن الند يقال فيما يشارك في الجوهر فقط والشبه يقال فيما يشارك في الكيفية فقط والمساوي يقال فيما يشارك في الكمية فقط والشكل يقال فيما يشاركه في القدر والمساحة فقط والمثل عام في جميع ذلك ولهذا لما أراد الله نفى التشبيه من كل وجه خصه بالذكر فقال: {لَيْسَ كَمِثْلِهِ شَيْءٌ} [الشورى: 11] وأما الجمع بين الكاف والمثل فقد قيل ذلك لتأكيد النفي تنبيها على أنه لا يصح استعمال المثل ولا الكاف فنفي بليس الأمرين جميعا وقيل المثل ها هنا بمعنى الصفة ومعناه: ليس كصفته صفه تنبيها على أنه وإن وصف بكثير مما يوصف به البشر فليستلك الصفاته له على حسب ما يستعمل في البشر.\r(2) ومما قاله الرازي في تفسير هذه الآية: يوم يكشف عن ساق جننم أو عن ساق العرش أو عن ساق ملك مهيب عظيم واللفظ لا يدل إلا على ساق فأما إن ذلك الساق ساق أي شيء هو فليس في اللفظ ما يدل عليه. ="], [17, "العلماء: يكشف عن شدة، وأنشدوا: «وقامت الحرب بنا على ساق» (1). وقال آخرون: إذا شمرت عن ساقها الحرب شمرا. قال ابن قتيبة: وأصل هذا أن الرجل إذا وقع في أمر عظيم يحتاج إلى معاناة الجد فيه، شمر عن ساقه، فاستعيرت الساق في موضع الشدة. وبهذا قال الفراء وأبو عبيد، وثعلب واللغويون. وروى البخاري ومسلم في الصحيحين عن النبي صلى الله عليه وسلم: «إن الله عز وجل يكشف عن ساقه» (2). هذه إضافة إليه معناها: يكشف عن شدته وأفعاله المضافة إليه ومعنى يكشف عنها: «يزيلها». وقال عاصم بن كليب: رأيت سعيد\r__________\r=وفي محاسن التأويل للعلامة الجمال القاسمي رحمه الله: وقال أبو سعيد الضرير: أي يوم يكشف عن أصل الأمر، وساق الشيء أصله الذي به قوامه كساق الشجر وساق الإنسان، أي تظهر يوم القيامة حقائق الأشياء وأصولها فالساق بمعنى أصل الأمر وحقيقته استعارة من ساق الشجر.\r(1) قال البيهقي في كتابه «الأسماء والصفات» عند الاستشهاد بهذا الكلام من الشعر: عن ابن عباس أنه سئل عن قوله تعالى {يَوْمَ يُكْشَفُ عَنْ سَاقٍ} [القلم: 42] فقال: إذا خفى عليكم شيء من القرآن فابتغوه من الشعر فإنه ديوان العرب.\r(2) في صحيح البخاري: ثنا آدم ثنا الليث عن خالد بن يزيد عن سعيد بن أبي هلاك عن زيد ابن أسلم عن عطاء بن يسار عن أبي سعيد قال سمعت النبي صلى الله عليه وسلم يقول: «يكشف ربنا عن ساقه فيسجد له كل مؤمن ومؤمنة» الحديث وقال الحافظ ابن حجر: ووقع في هذا الموضع «يكشف ربنا عن ساقه» وهو من رواية سعيد بن أبي هلال عن زيد بن أسلم فأخرجها الإسماعيلي كذلك ثم قال: في قوله عن ساقه نكرة، ثم أخرجه من طريق حفص بن ميسرة بن زيد بن أسلم بلفظ {يَوْمَ يُكْشَفُ عَنْ سَاقٍ} [القلم: 42] قال الإسماعيلي هذه أصح لموافقتها لفظ القرآن في الجملة اهـ.\rوقد أخذ ابن شاقلا على البخاري إخراجه حديث الساق في صحيحه لأنه من رواية ابن أبي هلال ويراه ليس من شرطه لضعفه. وقال ابن حزم أيضا: ابن أبي هلال ليس بالقوى قد ذكره بالتخليط يحيى وأحمد بن حنبل. (ز)"], [18, "بن جبير غضب وقال: يقولون يكشف عن ساقه، وإنما ذلك عن أمر شديد.\rوقد ذكر أبو عمر الزاهد ان الساق بمعنى «النفس» وقال: ومنه قول علي رضي الله عنه لما قالت البغاة: لا حكم إلا لله فقال: لا بد من محاربتهم ولو تلفت ساقي ... فعلى هذا يكون المعنى يتجلى لهم، وفي حديث أبي موسى عن النبي صلى الله عليه وسلم أنه قال: «يكشف لهم الحجاب فينظرون إلى الله تعالى فيخرون لله سجدا، ويبقى أقوام في ظهورهم مثل صياصي البقر، يريدون السجود فلا يستطيعون». فذلك قوله تعالى: {يَوْمَ يُكْشَفُ عَنْ سَاقٍ وَيُدْعَوْنَ إِلَى السُّجُوْدِ فَلَا يَسْتَطِيْعُوْنَ} [القلم: 42].\rوقد ذهب القاضي «أبو يعلى» إلى أن الساق صفة ذاتية. وقال مثله في «يضع قدمه في النار»: وحكى عن ابن مسعود: ويكشف عن ساقه اليمنى فتضئ من نور ساقه الأرض. قلت: وذكر الساق مع القدم تشبيه محض، وما ذكر عن ابن مسعود محال، ولا تثبت لله صفة بمثل هذه الخرافات، ولا توصف ذاته سبحانه بنور شعاع تضئ به الأرض، واحتجاجه بالاضافة ليس بشيء لأنه إذا كشف عن شدته، فقد كشف عن ساقه، وهؤلاء وقع لهم أن معنى يكشف «يظهر» وإنما المعنى «يزيل ويرفع».\rقال ابن حامد: يجب الايمان بأن لله تعالى ساقا صفة لذاته، فمن جحد ذلك كفر. قلت: ولو تكلم بهذا عامي"], [19, "جلف كان قبيحا، فكيف بمن ينسب إلى العلم؟! فإن المتأولين أعذر منهم لأنهم ردوا الامر إلى اللغة، وهؤلاء أثبتوا ساقا للذات، وقدما حتى يتحقق التجسيم والصورة.\rومنها قوله تعالى: {ثُمَّ اسْتَوَى عَلَى الْعَرْشِ} [الاعراف: 54] (1). قال الخليل بن أحمد: العرش: السرير، فكل سرير ملك يسمى عرشا، والعرش\r__________\r(1) يقول الآلوسي في تفسيره: والناس في الكلام على هذه الآية ونحوها مختلفون، فمنهم من فسر العرش بالمعنى المشهور وفسر الاستواء بالاستقرار وروى ذلك عن الكلبي ومقاتل ورواه البيهقي في (الأسماء والصفات) بروايات كثيرة عن جماعة من السلف وضعفها كلها، وما روى عن مالك رضي الله عنه أنه سئل كيف استوى فأطرق رأسه مليا حتى علته الرحضاء ثم رفع رأسه فقال: الاستواء غير مجهول والكيف غير معقول والغيمان به واجب والسؤال عنه بدعة ثم قال للسائل: وما أظنك إلا ضالا ثم أمر به فأخرج ليس نصا في هذا المذهب لاحتمال أن يكون المراد من قوله: (غير مجهول) أنه ثابت معلوم الثبوت لا أن معناه الاستقرار وهو غير مجهول. وقال في موضع آخر: وإلى نحو هذا ذهب الشيخ عز الدين بن عبد السلام فقال في بعض فتاويه: طريقة التأويل بشرطه وهو قرب التأويل أقرب إلى الحق لأن الله تعالى إنما خاطب العرب بما يعرفونه، وقد نصب الأدلة على مراده من آيات كتابه لأنه سبحانه قال: {ثُمَّ إِنَّ عَلَيْنَا بَيَانَهُ} [القيامة: 19] ولنبين للناس ما نزل إليهم، وهذا عام في جميع آيات القرآن فمن وقف على الدليل أفهمه الله مراده من كتابه وهو أكمل ممن لم يقف على ذلك إذ لا يستوي الذين يعلمون والذين لا يعلمون أهـ. وفيه توسط في المسألة، وقد توسط ابن الهمام في (المسايرة) وقد بلغ رتبة الاجتاد كما قال عصربنا ابن عابدين الشامي في (رد المحتار) توسطا أخص من هذا التوسط فذكر ما حاصله: وجوب الإيمان بأنه تعالى استوى على العرش مع نفى التشبيه، وأما كون المراد استولى فأمر جائز الإرادة لا واجبها إذ لا دليل عليه، وإذا خيف على العامة عدم فهم الاستواء إذا لم يكن بمعنى الاستيلاء إلا بالاتصال ونحوه من لوازم الجسمية فلا بأس بصرف فهمهم إلى الاستيلاء فإنه قد ثبت إطلاقه عليه لغة في قوله:\rفلما علونا واستوينا عليهم ... جعلناهم مرعى لنسر وطائر\rوقوله: قد استوى بشبر على العراق ... من غير سيف ودم مهراق (ز)"], [20, "مشهور عند العرب في الجاهلية والاسلام قال الله تعالى: {وَرَفَعَ أَبَوَيْهِ عَلَى الْعَرْشِ} [يوسف: 100]. وقال تعالى: {أَيُّكُمْ يَأْتِينِيْ بِعَرْشِهَا} [النحل: 38]. واعلم أن الاستواء في اللغة على وجوه منها: الاعتدال. قال بعض بني تميم فاستوى ظالم العشيرة والمظلوم. أي اعتدلا، والاستواء: تمام الشيء قال الله تعالى: {وَلَمَّا بَلَغَ أَشُدَّهُ وَاسْتَوَى} [القصص: 14] أي تم. والاستواء: القصد إلى الشيء قال تعالى: {ثُمَّ اسْتَوَى إِلَى السَّمَاءِ} [البقرة: 29] أي قصد خلقها، والاستواء الاستيلاء على الشيء قال الشاعر:\rإذا ما غزى قوما أباح حريمهم ... وأضحى على ما ملكوه قد استوى\rوروى إسماعيل بن أبي خالد الطائي قال: العرش ياقوتة حمراء. قلت: وجميع السلف على امرار هذه الآية كما جاءت من غير تفسير ولا تأويل.\rوقد حمل قوم من المتأخرين هذه الصفة على مقتضى الحس فقالوا: «استوى على العرش بذاته»، وهي زيادة لم تنقل، إنما فهموها من إحساسهم، وهو ان المستوي على الشيء إنما تستوي عليه ذاته، قال أبو حامد: الاستواء مماسته وصفة لذاته، والمراد به القعود (1).\r__________\r(1) قال الجلال الدواني في شرح العضدية: وقد رأيت في بعض تصانيف «ابن تيمية» القول به «أي بالقدم النوعي» في العرش اهـ وقال الشيخ محمد عبده فيما علقه عليه: وذلك أن ابن تيمية كان من الحنابلة الآخذين بظواهر الآيات والأحاديث القائلين بأن الله استوى على العرش جلوسا، فلما أورد عليه أنه يلزم أن يكون العرش أزليا لما أن الله أزلي فمكانه أزلي، وأزلية العرش خلاف مذهبه قال إنه قديم بالنوع أي أن الله لا يزال يعدم عرشا ويحدث آخر من الأزل إلى الأبد حتى يكون له الاستواء أزلا وأبدا ولننظر أين يكون الله بين ="]], "pg": [13, 20]}, "493.6": {"x": [[21, "قال: وقد ذهبت طائفة من أصحابنا إلى أن الله سبحانه وتعالى على عرشه قد ملأه، وأنه يقعد نبيه صلى الله عليه وسلم معه على العرش يوم القيامة. قال أبو حامد: والنزول هو انتقال.\rقلت: وعلى ما حكى تكون ذاته أصغر من العرش فالعجب من قول هذا، ما نحن مجسمة.\rوقيل لابن الزاغوني: هل تجددت له صفة لم تكن له بعد خلق العرش؟ قال: لا إنما خلق العالم بصفة التحت، فصار العالم بالاضافة إليه أسفل فإذا ثبت لاحدى الذاتين صفة التحت تثبت للاخرى صفة استحقاق الفوق قال: وقد ثبت أن الاماكن ليست في ذاته، ولا ذاته فيها، فثبت انفصاله عنها، ولا بد من شيء يحصل به الفصل، فلما قال: {اسْتَوَى} [الاعراف: 54] علمنا اختصاصه بتلك الجهة. قال ابن الزاغوني: ولا بد أن تكون لذاته نهاية وغاية يعلمها.\rقلت: وهذا رجل لا يدري ما يقول لأنه إذا قدر غاية وفصلا بين الخالق والمخلوق فقد حدده، وأقر بأنه جسم، وهو يقول في كتابه: إنه ليس بجوهر، لأن الجوهر ما تحيز ثم يثبت له مكانا يتحيز فيه. قلت: وهذا كلام جهل من قائله، وتشبيه محض، فما عرف هذا الشيخ ما يجب للخالق، وما يستحيل عليه.\r__________\r=الإعدام والإيجاد هل يزول عن الاستواء فليقل به أزلا، فسبحان الله ما أجهل الإنسان وما أشنع ما يرضى لنفسه، ولست أعرف هل قال ابن تيمية بشيء من ذلك على التحقيق، وكثيرا ما نقل عنه ما لم يقله أهـ. (ز)"], [22, "فإن وجوده تعالى ليس كوجود الجواهر والاجسام التي لا بد لها من حيز، والتحت والفوق إنما يكون فيما يقابل ويحاذي، ومن ضرورة المحاذي أن يكون أكبر من المحاذي أو أصغر أو مثله، وان هذا ومثله إنما يكون في الاجسام، وكل ما يحاذي الاجسام يجوز أن يمسها، وما جاز عليه مماسة الاجسام ومباينتها فهو حادث، إذ قد ثبت أن الدليل على حدوث الجواهر قبولها للمباينة والمماسة. فإذا أجازوا هذا عليه، قالوا بجواز حدوثه، وإن منعوا جواز هذا عليه، لم يبق لنا طريق لاثبات حدوث الجواهر، ومتى قدرناه مستغنيا عن المحل والحيز ومحتاجا إلى الحيز، ثم قلنا، إما أن يكونا متجاورين أو متباينين، كان ذلك محالا. فإن التجاور والتباين من لوازم التحيز في المتحيزات.\rوقد ثبت أن الاجتماع والافتراق من لوازم المتحيز، والحق سبحانه وتعالى لا يوصف بالتحيز، لأنه إن كان متحيزا لم يخل إما أن يكون ساكنا في حيزه، أو متحركا عنه، ولا يجوز أن يوصف بحركة ولا سكون، ولا اجتماع ولا افتراق، وما جاور أو باين فقد تناهى ذاتا، والمتناهي إذا خص بمقدار، استدعى مخصصا، وكذا ينبغي أن يقال، ليس بداخل في العالم وليس بخارج منه، لأن الدخول والخروج من لوازم المتحيزات وهما كالحركة والسكون وسائر الاعراض التي تختص بالاجرام."], [23, "وأما قولهم: خلق الاماكن لا في ذاته، فثبت انفصاله عنها. قلنا: ذاته تعالى لا تقبل أن يخلق فيها شيء، ولا أن يحل فيها شيء، والفصل من حيث الحس يوجب عليه ما يوجب على الجواهر، ومعنى الحيز أن الذي يختص به يمنع مثله أن يوجد، وكلام هؤلاء كله مبني على الحس، وقد حملهم الحس على التشبيه والتخليط حتى قال بعضهم: إنما ذكر الاستواء على العرش لأنه أقرب الموجودات إليه، وهذا جهل أيضا. لأن قرب المسافة لا يتصور إلا في حق الجسم. وقال بعضهم: جهة العرش تحاذي ما يقابله من الذات ولا تحاذي جميع الذات، وهذا صريح في التجسيم والتبعيض، ويعز علينا كيف ينسب هذا القائل إلى مذهبنا.\rواحتج بعضهم بأنه على العرش بقوله تعالى: {إِلَيْهِ يَصْعَدُ الْكَلِمُ الطَّيِّبُ وَالْعَمَلُ الصَّالِحُ} [فاطر: 10]. وبقوله تعالى: {وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ} [الأنعام: 18] وجعلوا ذلك فوقية حسية، ونسوا أن الفوقية الحسية إنما تكون لجسم أو جوهر وأن الفوقية قد تطلق لعلو المرتبة فيقال: فلأن فوق فلأن (1)، ثم إنه كما قال «فوق عباده» قال: {وَهُوَ مَعَكُمْ} [الحديد: 4]. فمن حملها على العلم، حمل خصمه الاستواء على القهر (2).\rوذهبت طائفة إلى أن الله تعالى على عرشه: قد ملأه،\r__________\r(1) في التفسير الكبير للفخر الرازي: العالم كرة وإذا كان الأمر كذلك امتنع أن يكون إله العالم حاصلا في جهة فوق، إذا فرضنا إنسانين وقف احدهما على نقطة المشرق والآخر على نقطة المغرب صار أخمص قدميهما متقابلين، والذي هو فوق بالنسبة لأحدهما يكون تحت بالنسبة إلى الثاني، وكونه تعالى تحت أهل الدنيا محال بالاتفاق فوجب أن لا يكون في حيز معين. (ز)\r(2) يقول الفخر الرازي في أساس التقديس: إن ظاهر قوله تعالى {وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ الْوَرِيدِ} [ق: 16] وقوله {وَهُوَ مَعَكُمْ أَيْنَ مَا كُنْتُمْ} [الحديد: 4] وقوله {وَهُوَ الَّذِي فِي السَّمَاءِ إِلَهٌ وَفِي الْأَرْضِ إِلَهٌ} [الزخرف: 84] ينفي كونه مستقرا على العرش، وليس تأويل هذه الآيات لتبقى الآيات التي تمسكوا بها على ظاهرها أولى من العكس أهـ. (ز)"], [24, "والاشبه أنه مماس للعرش والكرسي موضع قدميه. قلت: المماسة إنما تقع بين جسمين، وما أبقى هذا في التجسيم بقية.\r***\rفصل: فإن قيل: فقد أخرج في الصحيحين عن شريك بن عبد الله بن أبي نمر عن أنس بن مالك رضي الله عنه: أنه ذكر المعراج فقال فيه: «فعلا به إلى الجبار تعالى» فقال: «وهو في مكانه يا رب خفف عنا».\rفالجواب: ان أبا سليمان الخطابي قال: هذه لفظة تفرد بها شريك، ولم يذكرها غيره وهو كثير التفرد بمناكير الالفاظ، والمكان لا يضاف إلى الله عز وجل، إنما هو مكان النبي صلى الله عليه وسلم ومعناه: مقامه الأول الذي أقيم فيه». قال الخطابي: وفي هذا الحديث «فأستأذنت على ربي وهو في داره» - يوهم مكانا، وإنما المعنى، في داره التي دورها لاوليائه (1)، وقد قال القاضي «أبو يعلى» في كتابه «المعتمد»: إن الله عز وجل لا يوصف بالمكان.\rومن الآيات قوله تعالى: {أَأَمِنْتُمْ مَنْ فِي السَّمَاءِ} [الملك 16] (2). وقد\r__________\r(1) زاد البيهقي في كتابه الأسماء والصفات: «وهي الجنة».\r(2) قال الفخر الرازي في تفسير هذه الآية: أن هذه الآية لا يمكن إجراؤها على ظاهرها باتفاق المسلمين لأن كونه في السماء يقتضي كون السماء محيطا به من جميع الجوانب فيكون أصغر من السماء والسماء أصغر من العرش بكثير فيلزم أن يكون الله تعالى شيئا حقيرا بالنسبة إلى العرش، وذلك باتفاق أهل الإسلام محال وقال الزمخشري ووافقه الفخر: {مَنْ فِي السَّمَاءِ} [الملك 16] فيه وجهان أحدهما من ملكوته في السماء لأنها مسكن ملائكته وثم عرشه وكرسيه واللوح المحفوظ ومنها تنزل قضاياه وكتبه وأوامره ونواهيه، والثاني أنهم كانوا ="], [25, "ثبت قطعا أنها ليست على ظاهرها، لأن لفظة «في» للظرفية والحق سبحانه غير مظروف، وإذا منع الحس أن يتصرف في مثل هذا، بقي وصف العظيم بما هو عظيم عند الخلق. ومنها قوله تعالى: {يَاحَسْرَتَا عَلَى مَا فَرَّطْتُ فِي جَنْبِ اللهِ} [الزمر: 56] (1).\rأي في طاعته وأمره لان التفريط لا يقع إلا في ذلك، وأما الجنب المعهود من ذي الجوارح، فلا يقع فيه تفريط.\rوقال ابن حامد: نؤمن بأن لله تعالى جنبا بهذه الآية.\r__________\r=يعتقدون التشبيه وأنه في السماء وأن الرحمة والعذاب ينزلان منه وكانوا يدعونه من جهتها فقيل لهم على حسب اعتقادهم: أأمنتم من تزعمون أنه في السماء وهو متعال عن المكان أن يعذبكم بخسف أو بحاصب كما تقول لبعض المشبهة: أما تخاف من فوق العرش أن يعاقبك بما تفعل إذا رأيته يركب بعض المعاصي، وقال الرازي أيضا: والعرض من ذكر السماء تفخيم سلطان الله وتعظيم قدرته كما قال {وَهُوَ اللهُ فِي السَّمَاوَاتِ وَفِي الْأَرْضِ} [الأنعام: 3] فإن الشيء الواحد لا يكون دفعة واحدة في مكانين، وقال أيضا: لم لا يجوز أن يكون المراد بقوله {مَنْ فِي السَّمَاءِ} [الملك: 16] هو الملك الموكل بالعذاب وهو جبريل عليه السلام. (ز)\r(1) يقول الزمخشري في كشافه: والجنب الجانب، يقال: أنا في جنب فلان وجانبه وناحيته وفلان لين الجنب والجانب، ثم قالوا: فرط في جنبه وفي جانبه يريدون في حقه، قال سابق البربري:\rأما تتقين الله جنب وامق ... له كبد حرى عليك تقسطع\rوقال السيد محمود الآلوسي في تفسيره «روح المعاني»: وبالجملة لا يمكن إبقاء الكلام على حقيقته لتنزهه عز وجل من الجنب بالمعنى الحقيقي، ولم أقف على عد أحد من السلف إياه من الصفات السمعية، ولا أعول على ما في المواقف، وعلى فرض العد كلامهم فيها شهير وكلهم مجمعون على التنزيه وسبحان من ليس كمثله شيء وهو السميع البصير، وفي حرف عبد الله وحفصة «في ذكر الله». هـ وقال العلامة القاسمي في تفسيرها: أي في جانب أمره ونهيه إذ لم أتبع أحسن ما أنزل."], [26, "فواعجبا من عدم العقول، إذا لم يتهيأ التفريط في جنب مخلوق كيف يتهيأ في صفة الخالق جل جلاله وأنشد ثعلب وفسره: «خليلي كفا واذكرا الله في جنبي» أي في أمري.\rومنها قوله تعالى: {فَنَفَخْنَا فِيهِ مِنْ رُوحِنَا} [التحريم: 12} (1). قال المفسرون: أي من رحمتنا. وإنما نسب الروح إليه، لانه بأمره كان.\rومنها قوله تعالى: {يُؤْذُوْنَ اللهَ} [الأحزاب: 57] (2). قلت: أي يؤذون أولياءه كقوله تعالى: {وَاسْأَلِ الْقَرْيَةَ} [يوسف: 81] أي أهلها وقال النبي عليه الصلاة والسلام: «أحد جبل يحبنا ونحبه». وقال الشاعر:\rأنبئت أن النار بعدك أوقدت ... واستب بعدك يا كليب المجلس\rومنها قوله تعالى: {هَلْ يَنْظُرُونَ إِلَّا أَنْ يَأْتِيَهُمُ اللهُ فِي ظُلَلٍ مِنَ الْغَمَامِ} [البقرة 210] (3) أي بظلل. وكذلك قوله تعالى: {وَجَاءَ رَبُّكَ} [الفجر: 22]. ذكر\r__________\r(1) قال الشهاب الآلوسي: {وَنَفَخْتُ فِيْهِ مِنْ رُوْحِي} [الفجر: 29] تمثيل لإفاضة ما به الحياة بالفعل على المادة القابلة لها فليس ثمة نفخ ولا منفوخ، أي فإذا أكملت استعداده وأفضت عليه ما يحيا به من الروح الظاهرة التي هي أمري.\r(2) قال الآلوسي {إِنَّ الَّذِيْنَ يُؤْذُوْنَ اللهَ وَرَسُوْلَهُ} [الأحزاب: 57] أريد بالإيذاء إما ارتكاب ما لا يرضيانه من الكفر وكبائر المعاصي مجازا لأنه سبب أو لازم له، وإن كان ذلك بالنظر إليه تعالى بالنسبة إلى غيره سبحانه فإنه كاف في العلاقة، وقيل في إيذائه تعالى هو قول اليهود والنصارى والمشركين: يد الله مغلولة، والمسيح ابن الله، والملائكة بنات الله، والأصنام شركاؤه، تعالى الله عن ذلك علوا كبيرا.\r(3) ومما قاله جار الله الزمخشري: ويجوز أن يكون المأتى به محذوفا بمعنى أن يأتيهم الله ببأسه أو بنقمته للدلالة عليه بقوله {فَإِنَّ اللهَ عَزِيْزٌ} [الأنفال: 49]، فإن قلت: لم يأتيهم العذاب في الغمام؟ قلت: لأن الغمام مظنة الرحمة فإذا نزل منه العذاب كان الأمر أفظع وأهول لأن الشر إذا جاء من حيث لا يحتسب ="], [27, "القاضي «أبو يعلى» عن أحمد بن حنبل إنه قال: في قوله تعالى: {أَنْ يَأْتِيَهُمُ اللهُ} [البقرة: 210] قال المراد به: قدرته وأمره، قال: وقد بينه في قوله تعالى: {أَوْ يَأْتِيَ أَمْرُ رَبِّكَ} [النحل: 33] ومثل هذا في القرآن: {وَجَاءَ رَبُّكَ} [الفجر: 22] قال: إنما هو قدرته.\rقال ابن حامد: هذا خطأ، إنما ينزل بذاته بانتقال. قلت: وهذا الكلام في ذاته تعالى بمقتضى الحس، كما يتكلم في الاجسام.\r__________\r=كان أغم كما أن الخير إذا جاء من حيث لا يحتسب كان أسر، فكيف إذا جاء الشر من حيث يحتسب الخير، ولذلك كانت الصاعقة من العذاب المستفظع لمجيئها من حيث يتوقع الغيث، ومن ثمة اشتد على المتفكرين في كتاب الله قوله تعالى {وَبَدَا لَهُمْ مِنَ اللَّهِ مَا لَمْ يَكُونُوا يَحْتَسِبُونَ} [الزمر: 47] اهـ وساق الفخر الرازي في هذا المعنى فصلا مشبعا - شأنه في تفسير آيات الصفات - إلى أن قال: إن قوله {يَأْتِيَهُمُ اللهُ} [البقرة: 210] وقوله {وَجَاءَ رَبُّكَ} [الفجر: 22] إخبار عن حال القيامة، ثم ذكر هذه الواقعة بعينها في سورة النحل فقال {هَلْ يَنْظُرُوْنَ إِلَّا أَنْ تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ أَمْرُ رَبِّكَ} [النحل: 33] فصار هذا المحكم مفسرا لذلك المتشابه لأن كل هذه الآيات لما وردت في واقعة واحدة لم يبعد حمل بعضها على بعض، وقال تعالى بعده {وَقُضِيَ الْأَمْرُ} [البقرة: 210] ولا شك أن الألف واللام للمعهود السابق فلا بد وأن يكون قد جرى ذكر أمر قبل ذلك حتى تكون الألف واللام إشارة إليه وما ذاك إلا الذي أضمرناه من أن قوله {يَأْتِيَهُمُ اللهُ} [البقرة: 210] أي يأتيهم أمر الله، وأنهى كلامه بقوله: والذي هو أوضح عندي من كل ما سلف أنا ذكرنا أن قوله تعالى {يَاأَيُّهَا الَّذِيْنَ آمَنُوا ادْخُلُوْا فِي السِّلْمِ كَافَّةً} [البقرة: 208] إنما نزلت في حق اليهود، وعلى هذا التقدير فقوله {فَإِنْ زَلَلْتُمْ مِنْ بَعْدِ مَا جَاءَتْكُمُ الْبَيِّنَاتُ فَاعْلَمُوا أَنَّ اللهَ عَزِيْزٌ حَكِيْمٌ} [البقرة: 209] يكون خطابا مع اليهود، وحينئذ يكون قوله تعالى {هَلْ يَنْظُرُونَ إِلَّا أَنْ يَأْتِيَهُمُ اللهُ فِي ظُلَلٍ مِنَ الْغَمَامِ وَالْمَلَائِكَةُ} [البقرة 210]، حكاية عن اليهود، والمعنى أنهم لا يقبلون دينك إلا أن يأتيهم الله في ظلل من الغمام والملائكة، ألا ترى أنهم فعلوا مع موسى مثل ذلك فقالوا {لَنْ نُؤْمِنَ لَكَ حَتَّى نَرَى اللهَ جَهْرَةً} [البقرة: 55]، وإذا كان هذا حكاية عن حال اليهود لم يمنع إجراء الآية على ظاهرها، وذلك لأن اليهود كانوا على مذهب التشبيه وكانوا يجوزون على الله المجيء والذهاب، وكانوا يقولون: إنه تعالى يجلى لموسى عليه السلام على الطور في ظلل من الغمام وطلبوا مثل ذلك في زمن محمد عليه الصلاة والسلام."], [28, "قال ابن عقيل في قوله تعالى: (قل الروح من أمر ربي) الإسراء: 85.\rقال من كف خلقه عن السؤال عن مخلوق، فكفهم عن الخالق وصفاته أولى. وأنشدوا:\rكيفية النفس ليس المرء يدركها .... فكيف كيفية الجبار في القدم\r\rباب ذكر الأحاديث التي سموها أخبار الصفات\r"]], "pg": [21, 28]}, "493.7": {"x": [[28, "اعلم أن للاحاديث دقائق وآفات لا يعرفهما إلا العلماء الفقهاء، تارة في نظمها، وتارة في كشف معناها، وسنوضح بعض ذلك إن شاء الله تعالى:\rالحديث الأول: "]], "pg": [28, 28]}, "493.8": {"x": [[28, "روى البخاري ومسلم في الصحيحين من حديث أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «خلق الله آدم على صورته» (1).\rقلت: للناس في هذا مذهبان. أحدهما: السكوت عن تفسيره، والثاني: الكلام في معناه.\r__________\r(1) يقول الراغب الأصفهاني: الصورة أراد بها ما خص الإنسان من الهيئة المدركة بالبصر والبصيرة، وبها فضله على كثير من خلقه، وإضافته إلى الله سجانه على سبيل الملك لا على سبيل البعضية والتشبيه تعالى عن ذلك، وذلك على سبيل التشريف له كقوله بيت الله وناقة الله ونحو ذلك: ونفخت فيه من روحي."], [29, "واختلف أرباب هذا المذهب في الهاء على من تعود على ثلاثة أقوال:\rأحدها: تعود على بعض بني آدم، وذلك أن النبي صلى الله عليه وسلم مر برجل يضرب رجلا وهو يقول: قبح الله وجهك ووجه من أشبه وجهك. فقال: «إذا ضرب أحدكم فليتق الوجه فإن الله تعالى خلق آدم على صورته».\rوإنما خص آدم بالذكر، لانه هو الذي ابتدأت خلقة وجهه على هذه الصورة التي احتذي عليها من بعده، وكأنه نبه على أنك سببت آدم وأنت من أولاده وذلك مبالغة في زجره، فعلى هذا تكون الهاء كناية عن المضروب (1)، ومن الخطأ الفاحش أن ترجع إلى «الله عز وجل» لقوله: ووجه من أشبه وجهك فإنه إذا نسب إليه شبه سبحانه وتعالى كان تشبيها صريحًا.\rوفي صحيح مسلم من حديث أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم أنه قال: «إذا قاتل أحدكم فليتق الوجه، فإن الله تعالى خلق آدم على صورته».\r__________\r(1) مما أورده الرازي في تأويل هذا الخبر قوله: إن المراد منه إبطال قول من يقول إن آدم كان على صورة أخرى، مثل ما يقال إنه كان عظيم الجثة طويل القامة بحيث يكون رأسه قريبا من السماء فالنبي عليه السلام أشار إلى إنسان معين «وهو المضروب» وقال - إن الله خلق آدم على صورته - أي كان شكل آدم مثل شكل هذا الإنسان من غير تفاوت البتة. (ز)"], [30, "القول الثاني: «إن الهاء كناية عن إسمين ظاهرين، فلا يصح أن يضاف إلى الله عز وجل لقيام الدليل على أنه ليس بذي صورة، فعادت إلى آدم.\rومعنى الحديث: إن الله خلق آدم على صورته التي خلقه عليها تاما لم ينقله من نطفة إلى علقة كبنيه (1) هذا مذهب أبي سليمان الخطابي، وقد ذكره ثعلب في أماليه.\rالقول الثالث: «إنها تعود إلى الله تعالى» وفي معنى ذلك قولان: أحدهما: أن تكون صورة ملك، لانها فعله، فتكون إضافتها إليه من وجهين: أحدهما: التشريف بالاضافة كقوله تعالى: {أَنْ طَهِّرَا بَيْتِيَ لِلطَّائِفِينَ} [البقرة: 125]. والثاني: لانه ابتدعها على غير مثال سابق. والقول الثاني: أن تكون صورة بمعنى الصفة. تقول: هذا صورة هذا الامر: أي صفته، ويكون المعنى خلق آدم على صفته من الحياة والعلم والقدرة والسمع والبصر والارادة والكلام فميزه بذلك على جميع الحيوانات، ثم ميزه على الملائكة بصفة التعالي حين أسجدهم له. وقال ابن عقيل: إنما خص آدم بإضافة صورته إليه لتخصيصه وهي السلطنة التي تشاكلها الربوبية استعبادا وسجودا وأمرا نافذا وسياسات تعمر بها البلاد ويصلح به العباد وليس في الملائكة والجن من تجمع على طاعة نوعه وقبيلته سوى الآدمي. وإن الصورة ها هنا معنوية لا صورة تخاطيط.\r__________\r(1) ومن الوجوه التي سردها الفخر في هذا المقام قوله: أنه تعالى لما عظم أمر آدم بجعله مسجود الملائكة، ثم إنه أتى بتلك الزلة فالله تعالى لم يعاقبه بمثل ما عاقب به غيره فإن نقل أن الله تعالى أخرجه من الجنة وأخرج معه الحية والطاووس وغير تعالى خلقهما، مع أنه لم يغير خلقة آدم بل تركه على الخلقة الأولى إكراما له وصونا له عن عذاب المسخ هـ. وذهب البيهقي هذا المذهب. (ز)"], [31, "وقد ذهب أبو محمد بن قتيبة (1) في هذا الحديث إلى مذهب قبيح فقال: «لله صورة لا كالصور فخلق آدم عليها. .»؟؟ وهذا تخليط وتهافت لان معنى كلامه: إن صورة آدم كصورة الحق تعالى.\rوقال القاضي «أبو يعلى»: «يطلق على الحق تسمية الصورة لا كالصور كما أطلقنا اسم ذاته».\rوهذا تخليط، لان الذات بمعنى الشيء، وأما الصورة فهي هيئة وتخاطيط وتأليف، وتفتقر إلى مصور ومؤلف.\rوقول القائل لا كالصور، نقض لما قاله، وصار بمثابة من يقول: جسم لا كالاجسام، فإن الجسم ما كان مؤلفا، فإذا قال: لا كالاجسام نقض ما قال.\r***\rالحديث الثاني: "]], "pg": [28, 31]}, "493.9": {"x": [[31, "روى عبد الرحمن بن عائش رضي الله عنه عن النبي صلى الله عليه وسلم أنه قال: «رأيت ربي في أحسن صورة، فقال لي: فيم يختصم الملا الاعلى يا محمد قلت: أنت أعلم يا رب، فوضع كفه بين كتفي، حتى وجدت بردها بين ثدي، فعلمت ما في السموات والأرض.\r__________\r(1) هو صابح التصانيف أبو محمد عبد الله بن مسلم بن قتيبة أحد أئمة الأدب، إخباري، قليل الرواية، قد يعتمد في التشبيه على ما يرويه من كتب أهل الكتاب، يتهم بالنصب، كذبه الحاكم ووثقه غيره، مات عام ست وسبعين ومائتين. (ز)"], [32, "قال الإمام أحمد: أصل هذا الحديث وطرقه مضطربة روي من حديث أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «أتاني آت في أحسن صورة. فقال: فيم يختصم الملا الاعلى. .؟ فقلت: لا أدري، فوضع كفه بين كتفي، فوجدت بردها بين ثدي، فعرفت كل شيء يسألني عنه». وروي من حديث ثوبان قال: خرج علينا رسول الله صلى الله عليه وسلم بعد صلاة الصبح، فقال: «إن ربي أتاني الليلة في أحسن صورة فقال لي: يا محمد: فيم يختصم الملا الاعلى؟ قلت: لا أدري يا رب، فوضع كفه بين كتفي، حتى وجدت برد أنامله في صدري، فتجلى لي ما بين السماء والأرض».\rوهذه أحاديت مختلفة، وأحسن طرقها يدل على أن ذلك كان في النوم ورؤيا المنام وهم والأوهام لا تكون حقائق (1). وأن الانسان يرى كأنه يطير أو كأنه قد صار بهيمة وقد رأى أقوام في منامهم الحق سبحانه على ما ذكرنا وإن قلنا إنه رآه في اليقظة فالصورة إن قلنا ترجع إلى الله تعالى، فالمعنى رأيته على أحسن صفاته من الاقبال علي والرضى عني، وإن قلنا ترجع إلى رسول الله صلى الله عليه وسلم، فالمعنى رأيته وأنا على أحسن صورة (2). وروى ابن حامد من حديث ابن عباس\r__________\r(1) يقول الحافظ ابن حجر في مثل هذا المقام: ولا التفات إلى من تعقب كلامه بقوله: في الحديث الصحيح «أن رؤيا الأنبياء وحي» فلا يحتاج إلى تعبير لأنه كلام من لم يمعن النظر في هذا المحل، فقد تقدم في كتاب التعبير أن بعض رؤي الأنبياء يقبل التعبير اهـ (ز)\r(2) بقي على المؤلف أن يتكلم على عجز الحديث، ونحن ننقل عن «أساس التقديس للفخر الرازي» ما بقي بالغرض: وأما قوله «وضع يده بين كتفي» ففي وجهان: الأول المراد ="], [33, "رضي الله عنهما عن النبي صلى الله عليه وسلم أنه قال: «ولما أسرى بي رأيت الرحمن تعالى في صورة شاب أمرد، له نور يتلألأ، وعن عن (1). وصفه لكم، فسألت ربي أن يكرمني برؤيته، وإذا هو كأنه عروس حين كشف عن حجابه مستو على عرشه». قلت: هذا الحديث كذب قبيح. ما روي قط لا في صحيح ولا في كذب. فأبعد الله من عمله، فقد كنا نقول: ذلك في المنام، فذكر (الوضاع) هذا في ليلة الإسراء كافأهم الله وجزاهم النار، يشبهون الله سبحانه بعروسما كتب هذا مسلم، وأما الحديث البرد في الماضي، فإن البرد عرض، لا يجوز أن ينسب إلى الله عز وجل.\rوقد ذكر القاضي «أبو يعلى» في كتاب الكفاية عن أحمد: «رأيت ربي في أحسن صورة»، أي: في أحسن موضع.\rالحديث الثالث: "]], "pg": [31, 33]}, "493.10": {"x": [[33, "روت أم طفيل امرأه أبي بن كعب رضي الله عنهما، أنها سمعت رسول الله صلى الله عليه وسلم يذكر أنه: «رأى ربه عز وجل في المنام في أحسن صورة، شابا موفرا، رجلاه في خضرة، عليه نعلان من ذهب، على وجهه فراش من ذهب». هذا الحديث يرويه نعيم بن حماد قال ابن\r__________\r=منه المبالغة في الاهتمام بحاله والاعتناء بشأنه. الثاني أن يكون المراد من اليد النعمة، وأما قوله «بين كتفي» فإن صح فالمراد منه أنه أوصل إلى قلبه من أنواع اللطف والرحمة، وأما قوله (فوجدت بردها) فيحتمل أن المعنى برد النعمة وروحها وراحتها، من قولهم: عيش بارد إذا كان رغدا، والذي يدل على أن المراد منه كمال المعارف قوله عليه السلام في آخر الحديث «فعلمت ما بين المشرق والمغرب» اهـ. (ز)\r(1) هكذا في الأصل المحفوظ لدينا."], [34, "عدي: كان يضع الحديث. سئل الإمام أحمد فأعرض بوجهه عنه وقال: هذا حديث منكر مجهول. وعن ابن عباس رضي الله عنه عن رسول الله صلى الله عليه وسلم أنه قال: «رأيت ربي أجعد أمرد عليه حلة خضراء». وهذا مروي من طريق حماد بن سلمة وكان ابن أبي العوجاء الزنديق ربيب حماد، وكان يدس في كتبه هذه الاحاديث الاحاديث لا ثبوت لها، ولا يحسن أن يحتج بها.\rوقد أثبت بها القاضي «أبو يعلى» صفات لله تعالى فقال: قوله: شاب، وأمرد، وجعد، وقطط، والفراش والنعلان والتاج. قال: ثبت ذلك تسمية لا يعقل معناها، وليس في إثباتها أكثر من تقريب المحدث من القديم وذلك جائز كما روي «يدني عبده إليه» يعني يقربه إلى ذاته. قلت: ومن يثبت بالمنام وبما لا يصح نقله صفات؟! وقد عرفنا معنى الشاب والامرد ثم يقول: ما هو كما نعلم، كمن يقول: قام فلان وما هو قائم، وقعد وليس بقاعد. قال ابن عقيل: هذا الحديث مقطوع بأنه كذب. ثم لا تنفع ثقة الرواة إذا كان المتن مستحيلا، وصار هذا كما لو أخبرنا جماعة من المعدلين: بأن جمل البزاز دخل في خرم إبرة الخياط. فإنه لا حكم لصدق الرواة مع استحالة خبرهم.\r***\rالحديث الرابع: "]], "pg": [33, 34]}, "493.11": {"x": [[34, "روي عن أنس قال: قال رسول الله صلى الله عليه وسلم «انتهيت ليلة أسري بي إلى السماء فرأيت ربي، فرأيت كل شيء من ربي، حتى لقد رأيت تاجا مخوصا من لؤلؤ». قلت: هذا يرويه أبو القاسم عبد الله بن محمد بن اليسع عن القاسم بن إبراهيم. قال الأزهري: كنت أقعد مع ابن اليسع ساعة فيقول: «قد ختمت الختمة منذ قعدت وقاسم ليس بشيء». قال الدارقطني: هو كذاب. قلت: كافأ الله تعالى من عمل هذا."], [35, "الحديث الخامس: "]], "pg": [34, 35]}, "493.12": {"x": [[35, "روى البخاري ومسلم في الصحيحين من حديث أبي هريرة رضي الله تعالى عنه عن النبي صلى الله عليه وسلم أنه قال: «يجمع الله الناس فيقول: من كان يعبد شيئا فليتبعه، فيتبعون ما كانوا يعبدون، وتبقى هذه الامة فيها منافقوها، فيأتيهم الله عز وجل في غير الصورة التي كانوا يعرفون فيقول: أنا ربكم. فيقولون نعوذ بالله منك هذا مكاننا حتى يأتينا ربنا. فإذا جاء ربنا عرفناه فيأتيهم في الصورة التي يعرفون، فيقول: أنا ربكم. فيقولون: أنت ربنا».\rوفي الصحيحين من حديث أبي سعيد عن النبي صلى الله عليه وسلم أنه قال: «فيأتيهم الجبار في غير الصورة التي رأوه فيها أول مرة. فيقول أنا ربكم، فيقولون أنت ربنا، فلا يكلمه إلا الأنبياء. فيقال: هل بينكم وبينه آية تعرفونها، فيقولون: الساق. فيكشف عن ساقه فيسجد له كل مؤمن» (1).\rإعلم أنه يجب على كل مسلم أن يعتقد أن الله سبحانه وتعالى، لا تجوز عليه الصورة التي هي هيئة وتأليف، قال أبو سليمان الخطابي: معنى فيأتيهم الله أي يكشف الحجاب لهم حتى يرونه عيانا كما كانوا عرفوه في الدنيا استدلالا فرؤيته بعد أن لم يكونوا رأوه بمنزلة إتيان الآتي ولم يكن شوهد من قبل.\rوقال بعض العلماء يأتيهم بأهوال القيامة، وصور\r__________\r(1) لقدم الكلام على هذا الحديث عند تفسير قوله تعالى {يَوْمَ يُكْشَفُ عَنْ سَاقٍ} [القلم: 42]."], [36, "الملائكة (1)، مما لم يعهدوا مثله في الدنيا، فيستعيذون من تلك الحال، ويقولون: إذا جاء ربنا عرفناه، أي أتى بما يعرفونه من لطفه، وهي الصورة التي يعرفون فيكشف عن ساق: أي عن شدة كأنه يرفع تلك الشدائد المهولة، فيسجدون شكرا، وقال بعضهم: صورة يمتحن إيمانهم بها، كما يبعث الدجال فيقولون: نعوذ بالله منك. وفي حديث أبي موسى عن رسول الله صلى الله عليه وسلم: «أن الناس يقولون: إن لنا ربا كنا نعبده في الدنيا فيقال: أو تعرفونه إذا رأيتموه فيقولون: نعم. فيقال: كيف تعرفونه ولم تروه. فيقولون: إنه لا شبيه له، فيكشف الحجاب فينظرون إلى الله عز وجل فيخرون سجدا». قال ابن عقيل: الصورة على الحقيقة تقع على الاشكال والتخاطيط، وذلك من صفات الاجسام، والذي صرفنا عن كونه جسما. الادلة القطعية كقوله: {لَيْسَ كَمِثْلِهِ شَيْءٌ} [الشورى: 11]. ومن الادلة العقلية: أنه لو كان جسما لكان صورة وعرضا، ولو كان حاملا الاعراض، جاز عليه ما يجوز على الاجسام، وافتقر إلى صانع، ولو كان جسما مع قدمه، جاز قدم أحدنا، فأحوجتنا الادلة إلى تأويل صورة تليق أضافتها إليه، وما ذاك إلا الحال الذي يوقع عليه أهل اللغة اسم صورة فيقولون كيف صورتك مع فلان، وفلان على صورة من الفقر. والحال التي أنكروها العسف، والتي يعرفونها اللطف. فيكشف\r__________\r(1) باعتبار (في) بمعنى الباء، ونظيره قول ابن عباس في قوله تعالى {هَلْ يَنْظُرُونَ إِلَّا أَنْ يَأْتِيَهُمُ اللهُ فِي ظُلَلٍ مِنَ الْغَمَامِ} [البقرة 210] أي بظلل من الغمام على ما نقله الفخر الرازي في كتابه «أساس التقديس». (ز)"], [37, "عن الشدة، والتغير إنما يليق بفعله، فأما ذاته فتعالت عن التغير نعوذ بالله أن يحمل الحديث على ما قالته المجسمة إن الصورة ترجع إلى ذاته، فإن في ذلك تجويز التغير على صفاته. فخرجوه في صورة إن كانت حقيقية، فذلك استحالة. وإن كانت تخيلا فليس ذلك هو، إنما يريهم غيره.\r***\rالحديث السادس: "]], "pg": [35, 37]}, "493.13": {"x": [[37, "روى مسلم في صحيحه من حديث المغيرة عن رسول الله صلى الله عليه وسلم أنه قال: «لا شخص أغير من الله، ولا شخص أحب إليه العذر من الله، ولا شخص أحب إليه المدحة من الله».\rلفظة «الشخص» يرويها بعض الرواة، ويروي بعضهم «لا شيء أغير من الله». والرواة يروون بما يظنون به المعنى فيكون لفظ شخص من تغيير الرواة، والشخص لا يكون إلا جسما مؤلفا، وسمي شخصا لان له شخوصا وارتفاعا والصواب أنه يرجع ذكر الشخص إلى المخلوقين لا أن الخالق يقال له شخص، ويكون المعنى: «ليس منكم أيها الاشخاص أغير من الله»، لانه لما اجتمع الكل بالذكر، سمى بأسمائهم. ومثل هذا قول ابن مسعود: «ما خلق الله من جنة ولا نار أعظم من آية الكرسي». قال الإمام أحمد بن حنبل رحمه الله تعالى: الخلق يرجع إلى الجنة، والنار لا إلى القرآن ويجوز أن يكون هذا من باب المستثنى من غير الجنس كقوله تعالى: {مَا لَهُمْ بِهِ مِنْ عِلْمٍ إِلَّا اتِّبَاعَ الظَّنِّ} [النساء: 157]. وأما الغيرة: فقد قالت العلماء: كل من غار من شيء اشتدت كراهيته له، فلما حرم الفواحش وتوعد عليها وصفه رسوله صلى الله عليه وسلم بالغيرة."], [38, "الحديث السابع: "]], "pg": [37, 38]}, "493.14": {"x": [[38, "روى أبو موسى الاشعري رضي الله عنه عن النبي صلى الله عليه وسلم قال: «إن الله تعالى خلق آدم من قبضة قبضها من جميع الأرض» (1).\rوإنما أضيفت القبضة إليه لان أفعال المملوك تنسب إلى المالك، وذلك أنه بعث من قبض كقوله تعالى: {فَطَمَسْنَا أَعْيُنَهُمْ} [القمر: 37.] وقد روى محمد بن سعد في كتاب الطبقات: ان الله تعالى بعث إبليس فأخذ من أديم الأرض فخلق منه آدم فمن ثم قال {أَأَسْجُدُ لِمَنْ خَلَقْتَ طِينًا} [الإسراء: 61].\r***\rالحديث الثامن: "]], "pg": [38, 38]}, "493.15": {"x": [[38, "روى سليمان قال: «إن الله تعالى لما خمر طينة آدم ضرب بيديه فيه، فخرج كل طيب في يمينه، وكل خبيث في يده الاخرى، ثم خلط بينهما، فمن ثم يخرج الحي من الميت ويخرج الميت من الحي».\rوهذا مرسل وقد ثبت بالدليل أن الله سبحانه وتعالى لا يوصف بمس شيء، فإن صح فضرب مثل لما جرت به الاقدار. وقال القاضي «أبو يعلى»: تخمير الطين وخلط بعضه ببعض مضاف إلى اليد التي خلق بها آدم. وهذا التشبيه المحض.\r__________\r(1) يقول السيوطي في الجامع الكبير: أخرجه أبو داود والترمذي وأحمد والحاكم والبيهقي في السنن والطبراني في الكبير وابن سعد."], [39, "الحديث التاسع: "]], "pg": [38, 39]}, "493.16": {"x": [[39, "روى عبيد بن حنين قال: بينما أنا جالس في المسجد، إذ جاء قتادة بن النعمان فجلس يتحدث ثم قال: «انطلق بنا إلى أبي سعيد الخدري، فإني قد أخبرت أنه قد اشتكى، فانطلقنا حتى دخلنا على أبي سعيد فوجدناه مستلقيا واضعا رجله اليمنى على اليسرى، فسلمنا عليه وجلسنا، فرفع قتادة يده إلى رجل أبي سعيد، فقرصها قرصة شديدة فقال أبو سعيد: سبحان الله يا ابن أم أوجعتني». فقال: ذلك أردت، إن رسول الله صلى الله عليه وسلم قال: «إن الله لما قضى خلقه، استلقى ثم وضع إحدى رجليه على الاخرى، ثم قال: لا ينبغي لاحد من خلقي أن يفعل هذا». قال أبو سعيد: لا جرم لا أفعله أبدا (1).\rقال عبد الله بن أحمد بن حنبل: ما رأيت هذا الحديث في دواوين الشريعة المعتمد عليها، وأما عبيد بن حنين فقال البخاري: لا يصح حديثه في أهل المدينة، وفي الحديث علة أخرى، وهي أن قتادة بن النعمان مات في خلافة عمر بن الخطاب رضي الله عنه، وعبيد بن حنين مات سنة خمس ومائة. وله خمس وسبعون سنة، في قول الواقدي،\r__________\r(1) روى الحافظ البيهقي هذا الخبر في «الأسماء والصفات» وقال: فهذا حديث منكر ولم أكتبه إلا من هذا الوجه وفليح بن سليمان - أحد رواته - مع كونه من شرط البخاري ومسلم فلم يخرجا حديثه هذا في الصحيح وهو عند الحفاظ غير محتج به، عن يحيى بن معين يقول: فليح ليس بالقوى. قال الشيخ: فإذا كان فليح بن سليمان المدني مختلفا في جواز الاحتجاج به عند الحفاظ لم يثبت بروايته مثل هذا الأمر العظيم أهـ. وذكر أيضا علة عدم اجتماع عبيد بقتادة. (ز)"], [40, "فتكون روايته عن قتادة بن النعمان منقطعة. قال الإمام أحمد: ثم لو صح طريقه احتمل أن يكون رسول الله صلى الله عليه وسلم حدث به عن بعض أهل الكتاب على طريق الانكار عليهم، فلم يفهم قتادة إنكاره.\rومن هذا الفن حديث رويناه، أن الزبير سمع رجلا يحدث عن رسول الله صلى الله عليه وسلم فاستمع له الزبير حتى إذا قضى الرجل حديثه، قال له الزبير: «أنت سمعت هذا من رسول الله - صلى الله عليه وسلم، قال: نعم، قال: هذا وأشباهه يمنعنا أن نحدث عن رسول الله صلى الله عليه وسلم. قال: لعمري سمعت هذا من رسول الله صلى الله عليه وسلم وأنا يومئذ حاضر ولكن رسول الله صلى الله عليه وسلم ابتدأ بهذا الحديث، فحدثناه عن رجل من أهل الكتاب حدثه إياه، فجئت أنت يومئذ بعد انقضاء صدر الحديث، وذكر الرجل الذي من أهل الكتاب فظننت أنه من حديث رسول الله صلى الله عليه وسلم. قلت: وغالب الظن أن الاشارة في حديث الزبير إلى حديث قتادة، فإن أهل الكتاب قالوا: إن الله تعالى لما خلق السموات والأرض استراح فنزل قوله تعالى: {وَمَا مَسَّنَا مِنْ لُغُوبٍ} [ق 38]. فيمكن أن يكون رسول الله صلى الله عليه وسلم حكى ذلك عنهم، ولم يسمع قتادة أول الكلام.\rوقد روى أبو عبد الرحمن ابن أحمد في كتاب «السنة» عن أبي سفيان قال: «رأيت الحسن قد وضع رجله اليمنى على شماله وهو قاعد، فقلت: يا أبا سعيد تكره هذه القعدة.؟ فقال: قاتل الله اليهود ثم قرأ: {وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ وَمَا مَسَّنَا مِنْ لُغُوبٍ} [ق 38]."], [41, "فعرفت ما عنى فامسكت. قلت: إنما أشار الحسن إلى ما ذكرناه عن اليهود.\rوقد صح عن رسول الله صلى الله عليه وسلم، وأبي بكر وعمر، أنهم كانوا يستلقون ويضعون رجلا على رجل وإنما يكره هذا لمن لا سراويل له.\r***\rالحديث العاشر: "]], "pg": [39, 41]}, "493.17": {"x": [[41, "روى القاضي «أبو يعلى» عن حسان ابن عطية ان رجلا من المشركين سب رسول الله صلى الله عليه وسلم فحمل عليه رجل من المسلمين فقاتله وقتل الرجل. فقال رسول الله صلى الله عليه وسلم: «ما تعجبون من نصر الله ورسوله لقي الله متكئا فقعد له».\rهذا حديث مقطوع بعيد عن الصحة، ولو كان له وجه كان المعنى: فأقبل الله تعالى عليه وأنعم.\r***\rالحديث الحادي عثسر: "]], "pg": [41, 41]}, "493.18": {"x": [[41, "روى البخاري ومسلم في الصحيحين من حديث أنس بن مالك رضي الله عنه عن النبي صلى الله عليه وسلم قال: «لا تزال جهنم يلقى فيها وتقول: هل من مزيد، حتى يضع رب العزة فيها قدمه فينزوي بعضها إلى بعض» (1).\r__________\r(1) يقول جار الله الزمخشري في كتابه «الفائق في غريب الحديث»: وضع القدم على الشيء مثل للردع والقمع، فكأنه قال: يأتيها أمر الله فيكفها عن طلب المزيد فترتدع هـ. ="], [42, "قلت: الواجب علينا أن نعتقد أن ذات الله تعالى لا تتبعض ولا يحويها مكان ولا توصف بالتغير ولا بالانتقال. وقد حكى أبو عبيد الهروي عن الحسن البصري أنه قال: القدم: هم الذين قدمهم الله تعالى من شرار خلقه وأثبتهم لها. وقال: أبو منصور الأزهري: القدم هم الذين قدم الله بتخليدهم في النار فعلى هذا يكون في المعنى وجهين أحدهما: كل شيء قدمه. يقال: لما قدم قدم، ولما هدم هدم، ويؤيد هذا قوله في تمام الحديث «وأما الجنة فينشيء لها خلقا».\rووجه ثان: إن كل قادم عليها سمي قادما، فالقدم جمع قادم. ومن يرويه بلفظ «الرجل» فإنه يقال: «رجل من جراد» فيكون المراد: يدخلها جماعة يشبهون في كثرتهم الجراد، فيسرعون التهافت فيها.\rقال القاضي «أبو يعلى»: القدم صفة ذاتية. وقال ابن الزاغوني: نقول إنما وضع قدمه في النار ليخبرهم أن أصنافهم تحترق وأنا لا أحترق وهذا إثبات تبعيض، وهو من أقبح الاعتقادات.\rورأيت أبا بكر بن خزيمة قد جمع كتابا في الصفات (1) وبوبه فقال: باب إثبات اليد، باب امساك السموات على أصابعه، باب إثبات الرجل وإن رغمت أنوف المعتزلة، ثم قال: قال الله تعالى: {أَلَهُمْ\r__________\r=وفي أساس البلاغة: من المجاز «فيضع قدمه عليها» أي فيسكنها ويكسر سورتها كما يضع الرجل قدمه على الشيء المضطرب فيسكنه.\r(1) وهو الكتاب الذي يسميه «كتاب التوحيد»، والإمام فخر الدين الرازي يقول عنه: «وهو في الحقيقة كتاب الشرك». (ز)"], [43, "أَرْجُلٌ يَمْشُونَ بِهَا أَمْ لَهُمْ أَيْدٍ يَبْطِشُونَ بِهَا} [الاعراف: 69]، فأعلمنا أن من لا يد له ولا رجل فهو كالانعام.\rقال ابن عقيل: تعالى الله أن يكون له صفة تشغل الامكنة، هذا عين التجسيم، وليس الحق بذي أجزاء وأبعاض يعالج بها، ثم أليس يعمل في النار أمره وتكوينه؟ فكيف يستعين بشيء من ذاته ويعالجها بصفة من صفاته وهو القائل: {كُوْنِيْ بَرْدًا وَسَلَامًا} [الأنبياء: 69]، فما أسخف هذا الاعتقاد وأبعده عن مكون الاملاك والافلاك فقد كذبهم الله تعالى في كتابه إذ قال: {لَوْ كَانَ هَؤُلَاءِ آلِهَةً مَا وَرَدُوهَا} [الأنبياء: 99]، فكيف يظن بالخالق أنه يردها، تعالى الله عن تجاهل المجسمة.\r***\rالحديث الثاني عشر: "]], "pg": [41, 43]}, "493.19": {"x": [[43, "روى أبو هريرة رضي الله عنه عن النبي صلى الله عليه وسلم أنه قال: «ضرس الكافر مثل أحد، وكثافة جلده إثنان وأربعون ذراعا بذراع الجبار» (1).\rقال أبو عمر الزاهد: الجبار ها هنا الطويل، يقال: نخلة جبارة (2). قال ابن قتيبة: الجبار ههنا الملك، والجبابرة الملوك. قال القاضي «أبو يعلى»: نحمله على ظاهره. والجبار\r__________\r(1) يقول الشيخ إسماعيل العجلوني في كتابه «كشف الخفاء ومزيل الإلباس عما اشتهر من الأحاديث على ألسنة الناس»: رواه مسلم عن أبي هريرة مرفوعا وأحمد والطبراني والبيهقي عن ابن عمر مرفوعا، والترمذي عن أبي هريرة «بألفاظ متقاربة».\r(2) قال ابن قتيبة في كتابه «تأويل مختلف الحديث» في كلامه على هذا الحديث: ونحن نقول أن لهذا الحديث مخرجا حسنا إن كان النبي صلى الله عليه وسلم أراده وهو أن يكون الجبار ههنا الملك قال الله تعالى {وَمَا أَنْتَ عَلَيْهِمْ بِجَبَّارٍ} [ق: 45] أي بملك مسلط والجبابرة الملوك، وهذا ="], [44, "هو الله تعالى. قلت: واعجبا أذهبت العقول إلى هذا الحد! أو يجوز أن يقال: إن ذراع الله سبحانه إثنان وأربعون مرة حتى يبلغ جلد الكافر، ويضاف الذراع إلى ذات القديمة! تعالى الله عن ذلك علوا كبيرا.\r***\rالحديث الثالث عشر: "]], "pg": [43, 44]}, "493.20": {"x": [[44, "روى القاضي «أبو يعلى»: عن مجاهد أنه قال: إذا كان يوم القيامة يذكر داود عليه السلام ذنبه فيقول الله: «كن أمامي، فيقول: يا رب ذنبي، فيقول: كن خلفي، فيقول: يا رب ذنبي، فيقول: خذ بقدمي». قال: وفي لفظ عن ابن سيرين أن الله تعالى: ليقرب داود حتى يضع يده على فخذه.\rوالعجب من إثبات ذلك صفات للحق سبحانه وتعالى بأقوال التابعين، وما تصح عنهم، ولو صحت فإنما يذكرونها عن أهل الكتاب، كما يذكر وهب بن منبه. قال القاضي «أبو يعلى»: نحمله على ظاهره، لأننا لا نثبت قدما ولا فخذا هو جارحة.\rواعجبا لقد كملوا هيئة البدن باثبات فخذ وساق، وقدم، ووجه، ويدين وأصابع، وخنصر وإبهام وصعود ونزول، ويقولون تحمل على ظاهرها وليست جوارح.\rوهل يجوز لعاقل ان يثبت لله تعالى خلفا وإماما وفخذا!»\r__________\r=كما يقول الناس: هو كذا وكذا ذراعا بذراع الملك يريدون: بالذراع الأكبر، وأحسبه ملكا من ملوك العجم كان تام الذراع فنسب إليه."], [45, "ما ينبغي أن يحدث هؤلاء. ولانا قد عرفنا الفخذ فيقال: ليس بفخذ، والخلف ليس بخلف، ومثل هؤلاء لا يحدثون، فإنهم يكابرون العقول، وكأنهم يحدثون الأطفال.\r***\rالحديث الرابع عشر: "]], "pg": [44, 45]}, "493.21": {"x": [[45, "روى البخاري ومسلم في الصحيحين من حديث أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: «يضحك الله من رجلين يقتل أحدهما الآخر يدخلان الجنة». وفي أفراد مسلم من حديث ابن مسعود رضي الله عنه أن رسول الله صلى الله عليه وسلم أخبر عن آخر من يدخل الجنة وضحك، فقيل: مم تضحك؟ فقال: من ضحك رب العالمين.\rاعلم أن الضحك له معان ترجع إلى معنى البيان والظهور، وكل من أبدى عن أمر كان مستورا قيل قد ضحك. يقال: «ضحكت الأرض بالنبات» إذا ظهر ما فيها، وانفتق عن زهره، كما يقال: بكت السماء. قال الشاعر:\rكل يوم بالاقحوان جديد ... تضحك الأرض من بكاء السماء.\rوكذلك الضحك الذي يعتري البشر إنما هو انفتاح الفم عند الانسان، وهذا يستحيل على الله تعالى فوجب حمله على ابداء كرم الله، وإبانة فضله. ومعنى: «ضحكت لضحك ربي» أبديت عن أسناني بفتح فمي، لإظهار ربي فضله وكرمه. وقد روي في حديث موقوف: «ضحك حتى بدت لهواته وأضراسه» ذكره"], [46, "الخلال في كتاب السنة. وقال المروزي: قلت لابي عبد الله: ما تقول في هذا الحديث، قال: هذا يشفع. ثم يقول على تقدير الصحة يحتمل امرين: أحدها: أن يكون ذلك راجعا إلى النبي صلى الله عليه وسلم، كأنه ضحك حين أخبر بضحك الرب، حتى بدت لهواته وأضراسه صلى الله عليه وسلم، كما روي أنه ضحك حتى بدت لهواته واضراسه، وهذا هو الصحيح لو ثبت الحديث. الثاني: أن يكون تجوزا عن كثرة الكرم وسعة الرضا، كما جوز بقوله: «ومن أتاني يمشي أتيته هرولة».\rقال القاضي «أبو يعلى»: لا يمتنع الاخذ بظاهر الاحاديث في إمرارها على ظواهرها من غير تأويل.\rقلت: واعجبا قد أثبت لله صفات بأحاديث آحاد وألفاظ لا تصح. وقد أثبت الأضراس، فما عنده من الإسلام خبر.\r***\rالحديث الخامس عشر: "]], "pg": [45, 46]}, "493.22": {"x": [[46, "روى القاضي «أبو يعلى»: عن عبد الله بن عمرو موقوفا أنه قال: «خلق الله الملائكة من نور الذراعين والصدر».\rوقد أثبت به القاضي «أبو يعلى» ذراعين وصدرا لله عز وجل. وهذا قبيح، لانه حديث ليس بمرفوع ولا يصح، وهل يجوز أن يخلق مخلوق من ذات الله القديم! هذا أقبح مما ادعاه النصارى."], [47, "الحديث السادس عشر: "]], "pg": [46, 47]}, "493.23": {"x": [[47, "روى البخاري ومسلم في الصحيحين من حديث ابن عمر رضي الله عنهما، أن النبي صلى الله عليه وسلم قال: «إن الله يدني عبده المؤمن فيضع عليه كنفه ويقول: أتعرف ذنب كذا».\rقال العلماء: يدنيه من رحمته ولطفه. وقال ابن الانباري: وكنفه: حياطته وستره، يقال قد كنف فلان فلانا: إذا أحاطه وستره، ستر شيئا فقد كنفه، ويقال للترس كنيف لأنه يستر صاحبه.\rقال القاضي «أبو يعلى»: يدنيه من ذاته. وهذا قول من لم يعرف الله عز وجل، ولا يعلم أنه لا يجوز عليه الدنو الذي هو بالمسافة وكذلك قوله: انه ليدنو به يوم عرفة: أي يقرب بلطفه وعفوه.\r***\rالحديث السابع عشر: "]], "pg": [47, 47]}, "493.24": {"x": [[47, "روى مسلم في أفراده من حديث معاوية بن الحكم قال: «كانت لي جارية ترعى غنما لي، فانطلقت ذات يوم، فإذا الذئب قد ذهب بشاة، وأنا من بني آدم آسف كما يأسفون فصككتها صكة، فأتيت رسول الله صلى الله عليه وسلم فعظم ذلك علي. فقلت: ألا أعتقها، قال: «أئتني بها». فأتيته بها، فقال لها: «أين الله؟». قالت: في السماء. قال: «من أنا» قالت: أنت رسول الله. قال: «اعتقها فإنها مؤمنة»."], [48, "قلت: قد ثبت عند العلماء أن الله تعالى لا يحويه السماء والأرض ولا تضمه الاقطار، وإنما عرف بإشارتها تعظيم الخالق عندها.\r***\rالحديث الثامن عشر: "]], "pg": [47, 48]}, "493.25": {"x": [[48, "رواه أبو رزين العقيلي قال: قلت يا رسول الله: أين كان ربنا قبل أن يخلق الخلق؟ قال: «كان في عماء، ما تحته هواء، وما فوقه هواء، ثم خلق عرشه على الماء (1)».\rالعماء السحاب، إعلم أن الفوق والتحت يرجعان إلى السحاب لا إلى الله تعالى، و (في) معنى فوق، فالمعنى: كان فوق السحاب بالتدبير والقهر، ولما كان القوم يأنسون بالمخلومات، سألوا عنها، والسحاب من جملة خلقه، ولو سئل عما قبل السحاب، لاخبر أن الله تعالى كان ولا شيء معه، كذلك روي عن عمران بن حصين عن رسول الله صلى الله عليه وسلم أنه قال: «كان الله سبحانه وتعالى ولا شيء معه» ولسنا نختلف أن الجبار لا يعلوه شيء من خلقه بحال، وأنه لا يحل بالاشياء بنفسه، ولا يزول عنها، لانه لو حل بها لكان منها، ولو زال عنها لنأى عنها ..\r***\r__________\r(1) رواه الإمام أحمد في مسنده وابن جرير في تهذيب الآثار والطبراني في الكبير وأبو الشيخ في العظمة «جمع الجوامع للسيوطي»."], [49, "الحديث التاسع عشر: "]], "pg": [48, 49]}, "493.26": {"x": [[49, "روى البخاري ومسلم في الصحيحين من حديث أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم أنه قال: «ينزل ربنا كل ليلة إلى السماء الدنيا حتى يبقى ثلث الليل الاخير يقول: من يدعوني فاستجيب له».\rوقد روى حديث النزول عشرون صحابيا، وقد سبق القول انه يستحيل على الله عز وجل الحركة والنقلة والتغير. فيبقى الناس رجلين:\rأحدهما: المتأول له بمعنى: أنه يقرب رحمته. وقد ذكر أشياء بالنزول فقال تعالى: {وَأَنْزَلْنَا الْحَدِيدَ فِيهِ بَأْسٌ شَدِيْدٌ} [الحديد: 25] وإن كان معدنه بالأرض وقال: {أَنْزَلَ لَكُمْ مِنَ الْأَنْعَامِ ثَمَانِيَةَ أَزْوَاجٍ} [الزمر: 6]. ومن لم يعرف كيف نزول الجمل كيف يتكلم في تفصيل هذه الجمل.\rوالثاني: الساكت عن الكلام في ذلك مع اعتقاد التنزيه، والواجب على الخلق اعتقاد التنزيه وامتناع تجويز النقلة، وأن النزول الذي هو انتقال من مكان إلى مكان يفتقر إلى ثلاثة أجسام: جسم عالي، وهو مكان الساكن، وجسم سافل، وجسم ينتقل من علو إلى أسفل، وهذا لا يجوز على الله عز وجل.\rقال ابن حامد: هو على العرش بذاته، مماس له، وينزل من مكانه الذي هو فيه فيزول وينتقل. قلت: وهذا رجل لا يعرف ما يجوز على الله تعالى. وقال القاضي «أبو يعلى»: النزول صفة ذاتية، ولا نقول"], [50, "نزوله انتقال. قلت: وهذه مغالطة. ومنهم من قال: «يتحرك إذا نزل». وما يدري أن الحركة لا تجوز على الخالق. وقد حكوا عن الإمام أحمد ذلك وهو كذب عليه (1). ولو كان النزول صفة لذاته، لكانت صفاته كل ليلة تتجدد (2) وصفاته قديمة كذاته.\r***\r__________\r(1) حكى ذلك أبو يعلى في طبقاته عن أحمد بطريق أبي العباس الأصطخري، وهو كما قال المصنف نقل مفتري. وعجيب من ابن تيمية كتبه في معقوله - غير منكر - ما يرويه حرب ابن إسماعيل الكرماني صاحب محمد بن كرام في مسائله عن أحمد وغيره في حقه سبحانه ... يتكلم ويتحرك. . /هـ. ونقل أيضا عن نقض الدارمي - ساكتا أو مقرا - الحي القيوم يفعل ما يشاء ويتحرك إذا شاء ويهبط ويرتفع إذا شاء ويقبض ويبسط ويقوم ويجلس إذا شاء لأن أمارة ما بين الحي والميت التحرك وكل حي متحرك لا محالة وكل ميت غير متحرك لا محالة اهـ «أي ابن تيمية» حديث النزول فنزل عن المنبر درجتين فقال «كنزولي هذا» فنسب إلى التجسيم هـ.\r(2) مما يقوله ابن حزم الظاهري في حديث النزول: هذا إنما هو فعل يفعله الله تعالى في سماء الدنيا من الفتح لقبول الدعاء وأن تلك الساعة من مظان القبول والإجابة والمغفرة للمجتهدين والمستغفرين والتائبين، وهذا معهود في اللغة تقول: نزل فلان عن حقه لي بمعنى وهبه لي وتطول به على، ومن البرهان على أنه صفة فعل لا صفة ذات أن رسول الله صلى الله عليه وسلم علق التنزل المذكور بوقت محدود وصح أنه فعل محدث في ذلك الوقت مفعول حينئذ، وقد علمنا أن ما لم يزل فليس متعلقا بزمان البتة وقد بين رسول الله صلى الله عليه وسلم في بعض ألفاظ الحديث المذكور ما ذلك الفعل وهو أن ذكر عليه السلام أن الله يأمر ملكا ينادي في ذلك الوقت بذلك، وأيضا فإن ثلث الليل مختلف في البلاد باختلاف المطالع والمغارب يعلم ذلك ضرورة منم بحث عنه فصح ضرورة أنه فعل يفعله ربنا تعالى في ذلك الوقت لأهل كل أفق، وأما من جعل ذلك نقلة فقد قدمنا بطلان قوله في إبطال القول بالجسم / هـ. (ز)"], [51, "الحديث العشرين: "]], "pg": [49, 51]}, "493.27": {"x": [[51, "روى البخاري ومسلم في الصحيحين من حديث أبي هريرة رضي الله عنه. أن رجلا أتى إلى رسول الله صلى الله عليه وسلم فقال: «إني مجهود. فقال صلى الله عليه وسلم: من يضيف هذا هذه الليلة؟». فقام رجل من الأنصار فقال: أنا يا رسول الله، فانطلق به فقال لامرأته: هل عندك شيء؟ قالت: لا، إلا قوت صبياني. قال: فعلليهم بشيء وإذا أراد الصبية العشاء فنوميهم. فإذا دخل ضيفنا فأطفئي السراج، وأريه أنا نأكل. فقعدوا وأكل الضيف، فلما أصبح غدا على رسول الله صلى الله عليه وسلم فقال: «لقد عجب الله من صنيعكما بضيفكما الليلة».\rوفي أفراد البخاري من حديث أبي هريرة رضي الله عنه - عن النبي - صلى الله عليه وسلم قال: «عجب ربك من قوم جئ بهم في السلاسل حتى يدخلهم الجنة».\rقال العلماء: العجب إنما يكون من شيء يدهم الأنسان مما لا يعلمه فيستعظمه وهذا لا يليق بالخالق سبحانه، لكن معناه: عظم قدر ذلك الشيء عند الله لأن المتعجب من شيء يعظم قدره عنده، ومعنى في السلاسل: أكرهوا على الطاعة التي بها يدخلون الجنة. وقال ابن الأنباري: معنى عجب ربك: زادهم إنعاما واحسانا، فعبر بعجب عن ذلك.\r***\rالحديث الحادي والعشرون: "]], "pg": [51, 51]}, "493.28": {"x": [[51, "روى البخاري، ومسلم من حديث أبي هريرة رضي الله عنه، عن النبي صلى الله عليه وسلم قال: «إن الله أشد"], [52, "فرحا بتوبة عبده إذا تاب، من أحدكم براحلته إذا وجدها».\rقال المصنف: من كان مسرورا بشيء راضيا به قيل له فرح، والمراد الرضا بتوبة التائب، ولا يجوز أن يعتقد في الله تعالى التأثر الذي يوجد في المخلوقين، فإن صفات الحق قديمة فلا تحدث له صفة.\r***\rالحديث الثاني والعشرون: "]], "pg": [51, 52]}, "493.29": {"x": [[52, "روى مسلم في أفراده من حديث أبي موسى قال: قام فينا رسول الله صلى الله عليه وسلم بخمس كلمات فقال: «إن الله لا ينام ولا ينبغي له أن ينام، يخفض القسط ويرفعه، حجابه النور لو كشفه لاحرقت سبحات وجهه ما انتهى إلى بصره من خلقه» (1).\rوقوله: حجابه النور: ينبغي أن يعلم أن هذا الحجاب للخلق عنه، لأنه لا يجوز ان يكون محجوبا لأن الحجاب يكون أكبر مما يستره، وكما أنه لا يجوز أن يكون لوجوده ابتداء ولا انتهاء لا يصح أن يكون لذاته نهاية، وإنما المراد: أن الخلق محجوبون عنه كما قال سبحانه وتعالى: {كَلَّا إِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوْبُوْنَ} [المطففين: 15]. وأما السبحات فجمع سبحة، ويقال ان السبحة جلال وجهه. ومنه قوله: «سبحان الله» وإنما\r__________\r(1) يقول النووي في شرح صحيح مسلم: والتقدير: لو أزال المانع من رؤيته وهو الحجاب المسمى نورا أو نارا وتجلى لخلقه لأحرق جلال ذاته جميع مخلوقاته. (ز)"], [53, "هو تعظيم له وتنزيه.\rوقال القاضي «أبو يعلى»: لا يمنع اطلاق حجاب من دون الله تعالى، لا على وجه الحد والمحاذاة. وهذا كلام مختلط لا ترضى به العوام.\r***\rالحديث الثالث والعشرون: "]], "pg": [52, 53]}, "493.30": {"x": [[53, "روى ابن عباس رضي الله عنهما عن النبي صلى الله عليه وسلم، أنه قال: «أهل الجنة يرون ربهم تعالى في كل جمعة، في رمال الكافور، وأقربهم منه مجلسا أسرعهم إليه يوم الجمعة».\rقوله: «في رمال الكافور» إشارة إلى الحاضرين. ثم في رمال الكافور وأقربهم منه أي أحظاهم عنده.\rوفي حديث آخر: المقسطون يوم القيامة على منابر من نور على يمين الرحمن». وقال بعضهم: «يمين العرش».\rوفي حديث «سوق الجنة» فلا يبقى في ذلك المجلس أحد إلا حاضره الله محاضرة. ويروى «خاصرة» بالخاء المعجمة، ومثل هذا لا يثبت، والمخاصرة: المصافحة. وقال القاضي «أبو يعلى»: لا يمتنع أن يكون الحق تعالى في رمال الكافور. قلت: فقد أقر بالحصر. ثم قال: لا على وجه الأنتقال، وهذا تلاعب. ثم قال: ولا يمتنع قربهم من الذات وهذا يضيع معه الحديث، واستدل بقوله: «ما منكم من أحد الا سيخلو به ربه». وقال: الخلوة عبارة عن القرب، ويجوز"], [54, "القرب من الذات. قلت: وقد سبق رد هذا.\r***\rالحديث الرابع والعشرون: "]], "pg": [53, 54]}, "493.31": {"x": [[54, "روى البخاري ومسلم في الصحيحين من حديث ابن مسعود رضي الله عنه قال: جاء رجل من اليهود إلى رسول الله صلى الله عليه وسلم فقال: «يا محمد إن الله يمسك السموات يوم القيامة على اصبع والأرضين على إصبع، والجبال على إصبع، والشجر على اصبع. وفي لفظ الماء والثرى على اصبع، ثم يهزهن». فضحك رسول الله صلى الله عليه وسلم وقال: {وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ .. } [الزمر: 67].\rقلت: ظاهر ضحك النبي صلى الله عليه وسلم الأنكار (1)، واليهود مشبهة ونزول الآية دليل على إنكار الرسول صلى الله عليه وسلم عليهم. وفي هذا معنى هذا الحديث قوله عليه الصلاة والسلام: «إن قلوب بني آدم بين أصبعين من أصابع الرحمن يقلبها كيف يشاء». ولما كان القلب بين إصبعين ذليلا مقهورا، دل بهذا على أن القلوب مقهورة لمقلبها.\rوقال القاضي «أبو يعلى»: غير ممتنع حمل الخبر على ظاهره في الاثبات، والاصبع صفة راجعة إلى الذات، لأنا لا نثبت أصابعا هي جارحة ولا أبعاضا. قلت: وهذا كلام مخبط لأنه إما أن يثبت جوارحا وإما أن يتأولها، فأما حملها على ظواهرها، فظواهرها الجوارح،\r__________\r(1) يستبعد ابن خزيمة - وهو ممن وقع في خطأ التشبيه - أن يكون ضحك الرسول صلى الله عليه وسلم إنكارا، وقد نقض الحافظ ابن حجر زعمه هذا في الفتح. (ز)"], [55, "ثم يقول: ليست أبعاضا، فهذا كلام قائم قاعد، ويضيع الخطاب لمن يقول هذا.\r***\rالحديث الخامس والعشرون: "]], "pg": [54, 55]}, "493.32": {"x": [[55, "روى البخاري ومسلم في الصحيحين من حديث ابن عمر رضي الله عنهما عن النبي صلى الله عليه وسلم أنه قال: «يطوي الله عز وجل السموات يوم القيامة بيده ثم يأخذهن بيده اليمنى ثم يقول: أنا الملك، أين الجبارون أين المتكبرون؟ ثم يطوي الأرض بشماله ثم يقول: أنا الملك أين الجبارون؟ أين المتكبرون ... ؟ (1)». هكذا رواه مسلم وهي أتم الروايات، قد ثبت بالدليل القاطع أن يد الحق سبحانه وتعالى ليست بجارحة وان قبضه للاشياء ليس مباشرة، ولا له كف. وإنما قرب رسول الله صلى الله عليه وسلم إلى الافهام ما يدركه الحس، فأما رواية «الشمال» فضعيف بالمرة، وقد صح عن رسول الله صلى الله عليه وسلم انه قال: «وكلتا يديه يمين مباركة (2)» وهذا يوهن ذكر الشمال.\r***\rالحديث السادس والعشرون: "]], "pg": [55, 55]}, "493.33": {"x": [[55, "روه الإمام أحمد رحمه الله في\r__________\r(1) في الذي بين أيدينا من نسخ صحيح مسلم زيادة «ثم يطوي الأرضين بشماله». (ز)\r(2) يقول القتيبي عند الكلام على هذا الحديث: إنما أراد بذلك معنى التمام والكمال لأن التيامن وتكره التياسر لما في اليمين من التمام وفي اليسار من النقص، ويجوز أن يريد العطاء باليدين جميعا لأن اليمنى هي المعطية فإذا كانت اليدان يمينين كان العطاء بهما وإلى هذا ذهب المرار حين قال:\rوأن على الإوانة من عقيل ... فتى كلتا اليدين له يمين (ز)"], [56, "مسنده من حديث أنس رضي الله عنه عن النبي صلى الله عليه وسلم في قوله تعالى: (فلما تجلى ربه للجبل) الاعراف: 143. قال: قال هكذا، يعني أنه أخرج طرف الخنصر، وفي لفظ: «فأومأ بخنصره فساخ. وروى ابن حامد: «فلما تجلى ربه للجبل» قال: خرج منه أول مفصل من خنصره.\rهذا الحديث تكلم فيه علماء الحديث وقالوا: لم يروه عن ثابت غير حماد بن سلمة وكان ابن أبي العوجاء الزنديق قد أدخل على حماد أشياء، فرواها في آخر عمره ولذلك تجافى أصحاب الصحيح الاخراج عنه، ومخرج الحديث سهل، وذلك أن النبي صلى الله عليه وسلم كان يقرب إلى الافهام بذكر الحسيات، فوضع يده على خنصره إشارة إلى أن الله تعالى أظهر اليسير من آياته.\r***\rالحديث السابع والعشرون: "]], "pg": [55, 56]}, "493.34": {"x": [[56, "روى القاضي «أبو يعلى» عن عكرمة أنه قال: «إذا أراد الله عز وجل أن يخوف عباده أبدى عن بعضه إلى الأرض فعند ذلك تتزلزل، وإذا أراد أن يدمدم على قوم تجلى لهم».\rقال القاضي «أبو يعلى»: أبدى عن بعضه، هو على ظاهره، وهو راجع إلى الذات على وجه لا يفضي إلى التبعيض.\rقلت: ومن يقول أبدى عن بعض ذاته، وما هو بعض لا يكلم. ثم إثبات البعض بكلام تابعي لو صح يخالف إجماع المسلمين فانهم أجمعوا أن الخالق لا يتبعض وإنما المراد أبدى عن آياته.\r***"], [57, "الحديث الثامن والعشرون: "]], "pg": [56, 57]}, "493.35": {"x": [[57, "روى أبو الأحوص الجشمي رضي الله عنه عن أبيه، أن رسول الله صلى الله تعليه وسلم قال له: لعلك تأخذ موساك فتقطع أذن بعضها فتقول هذه بحر، وتشق أذن الاخرى وتقول: صرم؟ قال: نعم. قال: فلا تفعل فإن موسى الله أحد من موساك، وساعد الله أشد من ساعدك.\rقال القاضي «أبو يعلى»: لا يمتنع حمل الخبر على ظاهره في إثبات الساعد صفة لذاته. والمراد بالساعد: القوة، لأن قوة الأنسان في ساعده. وكان ينبغي أن يثبت الموسى.\r***\rالحديث التاسع والعشرون: "]], "pg": [57, 57]}, "493.36": {"x": [[57, "روى أبو هريرة رضي الله عنه عن النبي صلى الله عليه وسلم أنه قال: «إن العبد إذا قام إلى الصلاة فإنه بين عيني الرحمن».\rقذ ذكرنا صفة العين في الآيات المذكورة قبل الاحاديث والمراد بالحديث أن الله تعالى يشاهد المصلي فليتأدب. وكذلك قوله: «فإن الله قبل رجهه» أي أنه يراه.\r***\rالحديث الثلاثون: "]], "pg": [57, 57]}, "493.37": {"x": [[57, "روى البخاري ومسلم في الصحيحين من حديث عائشة رضي الله عنها: «أن رسول الله صلى الله عليه وسلم دخل عليها وعندها امرأة. فقال: من هذه؟». قالت: فلانة تذكر من صلاتها. فقال: «مه عليكم"], [58, "ما تطيقون، فوالله لا يمل الله حتى تملوا». وفي لفظ: «لا يسأم الله حتى تسأموا.»\rقال العلماء: معنى الحديث لا يمل الله تعالى وإن مللتم. كما قال الشاعر:\rصليت منى هذيل بخرق ... لا يمل الشر حتى يملوا,\rالمعنى: لا يمل وإن ملوا، وإلا لم يكن له فضل عليهم، وقال قوم: من مل من شيء تركه. والمعنى. لا يترك الثواب ما لم يتركوا العمل، وأما الملل الذي هو كراهة الشيء والاستثقال له، ونفور النفس عنه والسآمة منه، فمحال في حقه تعالى، لأنه يقتضي تغيره وحلول الحوادث في حقه.\r***\rالحديث الحادي والثلاثون: "]], "pg": [57, 58]}, "493.38": {"x": [[58, "روت خولة بنت حكيم عن النبي صلى الله عليه وسلم أنه قال: «آخر وطأة وطئها الرحمن بوج».\rوبوج واد بالطائف، وهي آخر وقعة أوقعها الله بالمشركين على يد رسول الله صلى الله عليه وسلم. ومنه قوله: «اللهم اشدد وطأتك على مضر». والوطأة مأخوذة من القدم، وإلى هذا ذهب ابن قتيبة وغيره. وقال القاضي «أبو يعلى»: غير ممتنع على أصولنا، حمل هذا الخبر على ظاهره، وإن ذلك المعنى بالذات دون الفعل، لأنا حملنا قوله: «ينزل ويضع قدمه في النار» على الذات. وهذا الرجل يشير بأصولهم إلى ما يوجب"], [59, "التجسيم والأنتقال والحركة، وهذا مع التشبيه بعيد عن اللغة ومعرفة التواريخ وأدلة العقول، وإنما اغتر بحديث روي عن كعب أنه قال: «ووج مقدس، منه عرج الرب إلى السماء، ثم قضى خلق الأرض». وهذا لو صح عن كعب احتمل أن يكون حاكيا عن أهل الكتاب، وكان يحكي عنهم كثيرا، ولو قدرناه من قوله كان معناه: أن ذلك المكان آخر ما استوى من الأرض لما خلقت، ثم عرج الرب، أي عمد إلى خلق السماء وهو قوله: {ثُمَّ اسْتَوَى إِلَى السَّمَاءِ وَهِيَ دُخَانٌ} [فصلت: 11]. ويروى عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: «لما أسري بي، مر بي جبريل عليه السلام حتى أتى بي إلى الصخرة، فقال: يا محمد من هاهنا عرج ربك إلى السماء». وهذا يرويه بكر بن زياد، وكان يضع الحديث على الثقات، فإن قيل: قال ابن عباس: «استوى إلى السماء» صعد، قلنا: صعد أمره، إذ لا يجوز عليه الأنتقال والتغير.\r***\rواعلم أن الناس في أخبار الصفات على ثلاث مراتب:\r(أحداها): إمرارها على ما جاءت من غير تفسير ولا تأويل، إلا أن تقع ضرورة كقوله: {وَجَاءَ رَبُّكَ} [الفجر: 22] أي جاء أمره وهذا مذهب السلف."], [60, "المرتبة الثانية: التأويل وهو مقام خطر (1).\rوالمرتبة الثالثة: القول فيها بمقتضى الحس، وقد\r__________\r(1) يقول في شرح المشكاة: قال النووي في شرح مسلم: في هذا الحديث «حديث النزول» وشبهه من أحاديث الصفات وآياتها مذهبان مشهوران: فمذهب جمهور السلف وبعض المتكلمين الإيمان بحقيقتها على ما يليق به تعالى وأن ظاهرها المتعارف في حقنا غير مراد ولا نتكلم في تأوليها مع اعتقادنا تنزيه الله سبحانه عن سائر سمات الحدوث، والثاني مذهب أكثر المتكلمين وجماعة من السلف وهو محكي عن مالك والأوزاعي إنما يتأول على ما يليق بها بحسب بواطنها فعليه الخبر مؤول بتأويلين أي المذكورين. وبكلامه وبكلام الشيخ الرباني أبي إسحاق الشيرازي وإمام الحرمين والغزالي وغيرهم من أئمتنا وغيرهم يعلم أن المذهبين متفقان على صرف تلك الظواهر كالمجيء والصورة والشخص والرجل والقدم واليد والوجه والغضب والرحمة والاستواء على العرش والكون في السماء وغير ذلك عما يفهمه ظاهرها لما يلزم عليه من محالات قطعية البطلان تستلزم أشياء يحكم بكفرها بالإجماع، فاضطر جميع الخلف والسلف إلى صرف اللفظ عن ظاهره، وإنما اختلفوا هل نصرفه عن ظاهره معتقدين اتصافه سبحانه بما يليق بجلاله وعظمته من غير أن نؤوله بشيء آخر وهو مذهب أكثر أهل الخلف وهو تأويل تفصيل ولم يريدوا بذلك مخالفة السلف الصالح معاذ الله أن يظن بهم ذلك وإنما دعت الضرورة في أزمنتهم لذلك لكثرة المجسمة والجهمية وغيرهما من فرق الضلال واستيلائهم على عقول العامة، فقصدوا بذلك ردعهم وبطلان قولهم ومن ثمت اعتذر كثير منهم وقالوا: لو كنا على ما كان عليه السلف الصالح من صفاء العقائد وعدم المبطلين في زمنهم لم نخض في تأويل شيء من ذلك وقد علمت أن مالكا والأوزاعي وهما من كبار السلف أولا الحديث تأويلا تفصيليا وكذلك سفيان الثوري أول الاستواء على العرش بقصد أمره ونظيره «ثم استوى إلى السماء» أي قصد إليها ومنهم الإمام جعفر الصادق، بل قال جمع منهم ومن الخلف: أن معتقد الجهة كافر كما صرح به العراقي وقال أنه قول لأبي حنيفة ومالك والشافعي والأشعري والباقلاني، وقد اتفق سائر الفرق على تأويل نحو {وَهُوَ مَعَكُمْ أَيْنَ مَا كُنْتُمْ} [الحديد: 4] {مَا يَكُونُ مِنْ نَجْوَى ثَلَاثَةٍ إِلَّا هُوَ رَابِعُهُمْ} [المجادلة: 7] الآية {فَأَيْنَمَا تُوَلُّوْا فَثَمَّ وَجْهُ اللهِ} [البقرة: 115] {وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ الْوَرِيْدِ} [ق: 16] و «قلب المؤمن بين إصبعين من أصبع الرحمن» و «الحجر الأسود يمين الله في الأرض» وهذا الاتفاق يبين لك صحة ما اختاره المحققون أن الوقف على «الراسخون في العلم» لا الجلالة. قلت الجمهور على أن الوقف على «إلا الله» وعدوا وقفه وقفا ="], [61, "............................................................................................\r__________\r= لازما وهو الظاهر لأن المراد بالتأويل معناه الذي أراده تعالى وهو في الحقيقة لا يعلمه إلا الله جل جلاله ولا إله غيره، وكل من تكلم فيه تكلم بحسب ما ظهر له ولم يقدر أحد أن يقول إن هذا التأويل هو مراد الله جزما ففي التحقيق الخلاف لفظي ولهذا اختار كثيرون من محققي المتأخرين عدم تعيين التأويل في شيء معين من الأشياء التي تليق باللفظ ويكلون تعيين المراد بها إلى علمه تعالى، وهذا توسط بين المذهبين وتلذذ بين المشربين واختار ابن دقيق العيد توسطا آخر فقال إن كان التأويل من المجاز البين الشائع سلوكه من غير توقف أو من المجاز البعيد الشاذ فالحق تركه وإن استوى الأمران فالاختلاف في جوازه وعدمه مسألة فقهية اجتهادية والأمر فيها ليس بالخطر بالنسبة للفريقين. قلت التوقف فيها لعدم ترجيح أحد الجانبين مع أن التوقف مؤيد بقول السلف ومنهم الإمام الأعظم أهـ. ويقول في شرح المشكاة أيضا: والحاصل أن السلف والخلف مؤولون لإجماعهم على صرف اللفظ عن ظاهره ولكن تأويل السلف إجمالي لتفويضهم إلى الله تعالى وتأويل الخلف تفصيلي لاضطرارهم إليه لكثرة المبتدعين هـ.\rوفي «إشارة النبيه في كشف شبه أهل التشبيه إملاء الشيخ نجم الدين أبي الفتح نصر الله ابن العز بن سعد الله بن نجم الكاتب البغدادي»: وقد تأول العلماء والأدباء والشعراء قديما وحديثا ولذلك قول بعضهم:\rأقول بالخد خال حين أذكره… ... خوف الرقيب وما بالخد من خال\rأبكى إلى الشرق إن كانت منازلهم… ... يجانب الغرب خوف القيل والقال\rومن قال: «لا أقول بالتأويل ولا أشبه» فقد تأول لأنه إذا عدل عن معنى النزول عنده ومعنى اليمين في حديث «الحجر الأسود يمين الله في الأرض» إلى غير ذلك فقد تأول فلا محيص لكم عن التأويل بحال أهـ.\rويقول العلامة الآلوسي في تفسيره عند الكلام على الوجه: والتأويل القريب إلى الذهن الشائع نظيره في كلام العرب مما لا بأس به عندي، على أن بعض الآيات مما أجمع على تأويلها السلف والخلف والله تعالى أعلم بمراده هـ. وقال أيضا: وأنا أميل إلى التأويل وعدم القول بالظواهر مع نفى اللوازم في بعض ما ينسب إلى الله مثل قوله تعالى {سَنَفْرُغُ لَكُمْ أَيُّهَ الثَّقَلَانِ} [الرحمن: 31]، وقوله صلى الله عليه وسلم «الحجر الأسود يمين الله في أرضه فمن قبله أو صافحه فكأنما صافح الله تعالى وقبل يمينه» فأجعل الكلام فيه خارجا مخرج التشبيه لظهور القرينة، ولا أقول: الحجر الأسود من صفاته كما قال السلف في اليمين أهـ.\rوقد عقد ابن المعلم في كتابه «نجم المهتدي ورجم المعتدى» بابا سرد فيه جماهير المؤولين «فيما يظهر فيه وجه الكلام» من الصحابة والتابعين وغيرهم. (ز)"], [62, "عم جهلة الناقلين، إذ ليس لهم حظ من علوم المعقولات التي بها يعرف ما يجوز على الله وما يستحيل، فان علم المعقولات يصرف ظواهر المنقولات عن التشبيه، فإذا عدموها تصرفوا في النقل بمقتضى الحس. وإليه أشار القاضي «أبو يعلى» بقوله: «لا يمتنع أن تحمل الوطأة التي وطئها الحق على أصولنا وأنه معنى يتعلق بالذات». وأصولهم على زعمه ترجع إلى الحس.\rولو فهموا أن الله تعالى لا يوصف بحركة ولا انتقال ولا تغير، ما بنوا على الحسيات. والعجب أن يقر بهذا القول ثم يقول: «من غير نقلة ولا حركة» فينقض ما يبني.\rومن أعجب ما رأيت لهم ما ذكروه عن ابن أبي شيبة انه قال في كتاب «العرش»: إن الله تعالى قد أخبرنا أنه صار من الأرض إلى السماء، ومن السماء إلى العرش فاستوى على العرش».\rقلت: ونحن نحمد الله إذ لم يبخس حظنا من المنقولات، ولا من المعقولات ونبرأ من أقوام شانوا مذهبنا، فعابنا الناس كلامهم.\r***\rالحديث الثاني والثلاثون: "]], "pg": [58, 62]}, "493.39": {"x": [[62, "روى أبو إمامة رضي الله عنه عن النبي صلى الله عليه وسلم أنه قال: «ما تقرب العباد إلى الله تعالى، بمثل ما خرج منه (1)» وهو القرآن وفي حديث عثمان رضي الله عنه: ان النبي صلى الله عليه وسلم، قال «فضيلة القرآن على\r__________\r(1) الذي في الجامع الكبير للسيوطي: «ما تقرب العباد إلى الله بشيء أحبا إليه مما خرج منه» ابن السنى عن زيد بن أرطأ عن أبي أمامة."], [63, "سائر الكلام كفضل الله على خلقه إن القرآن منه خرج وإليه يعود»، والمعنى إنه وصل إلينا من عنده وإليه يعود فيرفع.\r***\rالحديث الثالث والثلاثون: "]], "pg": [62, 63]}, "493.40": {"x": [[63, "روى أبو هريرة رضي الله عنه عن النبي صلى الله عليه وسلم: «إن الله قرأ طه ويس قبل أن يخلق آدم بألف سنة، فلما سمعت الملائكة القرآن قالوا: طوبى لامة ينزل عليهم، وطوبى لاجواف تحمل هذا، وطوبى لألسن تتكلم به».\rوهذا حديث موضوع يرويه إبراهيم بن مهاجر عن عمر بن حفص، وأما عمر بن حفص فقال أحمد بن حنبل: حرقنا حديثه وقال يحيى بن معين: ليس بشيء، وقال أبو حاتم بن حبان الحافظ: وهذا متن موضوع.\r***\rالحديث الرابع والثلاثون: "]], "pg": [63, 63]}, "493.41": {"x": [[63, "روى البخاري ومسلم في الصحيحين من حديث أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم أنه قال: «إن الله عز وجل خلق الخلق حتى إذا فرغ منهم قامت الرحم فقالت: هذا مقام العائذ بك من القطيعة. قال: نعم: أما ترضين أن أصل من وصلك وأقطع من قطعك» (1). وفي لفظ أخرجه البخاري أن النبي صلى الله عليه وسلم قال: «إن الرحم\r__________\r(1) في شرح صحيح مسلم للإمام النووي: قال القاضي عياض: الرحم التي توصل وتقطع ="], [64, "شجنة من الرحمن».\rقال أبو عبيدة: الشجنة كالغصن من الشجرة، ومعنى شجنة أي: قرابة مشتبكة كاشتباك العروق، والشجر تشجن إذا إلتف بعضها ببعض.\rقلت: ولا يخلو هذا الحديث من أحد أمرين. اما أن يراد أن الله تعالى يراعي الرحم فيصل من وصلها ويقطع من قطعها ويأخذ لها حقا كما يراعي القريب قرابته، كأنه يزيد في المراعاة على الاجانب. أو أن يراد أن الرحم بعض حروف الرحمن، فكأنه عظم قدرها بهذا الاسم، ويؤيد هذا حديث عبد الرحمن بن عوف رضي الله عنه عن النبي صلى الله عليه وسلم: قال: قال الله تعالى: «أنا الله وأنا الرحمن خلقت الرحم وشققت لها اسما من اسمي فمن وصلها وصلته ومن قطعها قطعته». أو قال: «بتته». وقد روي هذا الحديث بلفظ لم يخرج في الصحاح: «الرحم شجنة من الرحمن تعلقت بحقوي الرحمن تقول: اللهم صل من وصلني واقطع من قطعني» وفي لفظ: «الرحم شجنة آخذة بحقو الرحمن»، وفي لفظ: «لما خلق الله الخلق قامت الرحم فأخذت بحقو الرحمن فقالت: هذا مقام العائذ بك من القطيعة». قلت: وهذه أمثال كلها ترجع إلى ما بينا، ومعنى تعلقها بحقو\r__________\r=وتبر إنما هي معنى من المعاني ليست بجسم وإنما هي قرابة ونسب تجمعه رحم والدة ويتصل بعضه ببعض فسمى ذلك الاتصال رحما، والمعنى لا يتأتى منه القيام ولا الكلام، فيكون ذكر قيامها هنا وتعلقها ضرب مثل وحسن استعارة على عادة العرب في استعمال ذلك، والمراد تعظيم شأنها وفضيلة واصليها وعظيم إثم قاطعيها بعقوقهم. (ز)"], [65, "الرحمن: الاستجارة والاعتصام. (1)\rقال أبو بكر البيهقي: الحقو الإزار، والمعنى: يتعلق بعزه.\rقال ابن حامد: يجب التصديق بأن لله تعالى حقوا، فتأخذ الرحم بحقوه. قال: وكذلك نؤمن بأن لله جنبا لقوله تعالى: {عَلَى مَا فَرَّطْتُ فِي جَنْبِ الهِ} [الزمر: 56].\rوهذا لا فهم له أصلا، كيف يقع التفريط في جنب الذات. نعوذ بالله من سوء الفهم.\r***\rالحديث الخامس والثلاثون: "]], "pg": [63, 65]}, "493.42": {"x": [[65, "روى مسلم في صحيحه (2) أن النبي صلى الله عليه وسلم قال: يقول الله عز وجل: «الكبرياء ردائي والعظمة ازاري فمن نازعني في شيء منهما عذبته».\rقال أبو سليمان الخطابي معنى الكلام: إن الكبرياء والعظمة صفتان لله تعالى: اختص بهما لا يشاركه فيهما أحد، ولا ينبغي لمخلوق ان يتعاطاهما، لأن صفة المخلوق التواضع والتذلل وضرب الازار والرداء مثلا يقول والله تعالى اعلم كما لا يشارك الإنسان\r__________\r(1) قال في النهاية: والحقو فيه مجاز وتمثيل ومنه قولهم: عزت بحقو فلان إذا استجرت به واعتصمت اهـ وفي أساس البلاغة: لاذ بحقويه إذا فزع إليه.\r(2) يقول العجلوني في كشف الخفا ومزيل الإلباس عما اشتهر من الأحاديث على ألسنة الناس: رواه مسلم وابن حبان وأبو داود وابن ماجه عن أبي هريرة والحاكم «بألفاظ متقاربة»، وممن أخرجه بلفظ الترجمة القضاعي عن أبي هريرة والحكيم الترمذي عن أنس هـ. ولم يذكر البخاري فليحرر."], [66, "في إزاره وردائه أحد، كذلك لا يشاركني في الكبرياء والعظمة مخلوق.\r***\rالحديث السادس والثلاثون: "]], "pg": [65, 66]}, "493.43": {"x": [[66, "روى البخاري ومسلم في الصحيحين من حديث أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: يقول الله تعالى: أنا عند ظن عبدي وأنا معه حيث يذكرني فإن ذكرني في نفسه ذكرته في نفسي، وإن ذكرني في ملا ذكرته في ملا خير منهم (177)، وإن تقرب إلي شبرا تقربت إليه ذراعا، وان تقرب إلي ذراعا اقتربت إليه باعا، وإن أتاني يمشي أتيته هرولة».\rفذهب القاضي «أبو يعلى» إلى أن لله نفسا هي صفة زائدة على الذات.\rوهذا قول مبتدع بنوع التشبيه لأنه لا يفرق بين الذات والنفس، وما المانع أن يكون المعنى: ذكرته أنا وقد سبق هذا في الكلام على الآيات، والتقرب والهرولة، توسع في الكلام (1) كقوله تعالى {سَعَوْا فِيْ آيَاتِنَا} [الحج: 50] لا يراد به المشي.\r***\rالحديث السابع والثلاثون: "]], "pg": [66, 66]}, "493.44": {"x": [[66, "روى أبو سعيد رضي الله عنه عن النبي صلى الله عليه وسلم أنه قال: «إن الله جميل يحب الجمال» (2).\r__________\r(1) في تأويل مختلف الحديث لابن قتيبة عند الكلام على التقرب والهرولة: ونحن نقول: إن هذا تمثيل وتشبيه وإنما أراد: من أتانى مسرعا بالطاعة أتيته بالثواب أسرع من إتيانه.\r(2) أثبت العجلوني في كشف الخفاء ومزيل الإلباس هذا الحديث وقال رواه أحمد عن أبي ريحانة، ومسلم والترمذي عن ابن مسعود، وأبو يعلى والبيهقي عن أبي سعيد، والطبراني عن أبي أمامة وابن عمر وجابر، وابن عدى في الكامل عن ابن عمر."], [67, "قال العلماء: الجميل المجمل بتحسين الصور والاخلاق والاحسان، والذي أراه أن الجميل الذي أوصافه تامة مستحسنة, وقد فسره القاضي أبو يعلى بما لا يليق بالحق سبحانه فقال: غير ممتنع وصفه بالجمال وإن ذلك صفة راجعة إلى الذات، لأن الجمال في معنى الحسن. قال: وقد تقدم قوله صلى الله عليه وسلم «رأيت ربي في أحسن صورة»\r***\rالحديث الثامن والثلاثون: "]], "pg": [66, 67]}, "493.45": {"x": [[67, "روى القاضي «أبو يعلى» عن عمر بن عبد العزيز: «ذا فرغ الله من أهل الجنة والنار أقبل يمشي في ظلل من الغمام والملائكة فيقف على أول درجة فيسلم عليهم، فيردون عليه السلام فيقول: سلوني. فيقولون: وماذا نسأل؟ وعزتك وجلالك وارتفاعك في مكانك لو أنك قسمت علينا رزق الثقلين لاطعمناهم وأسقيناهم ولم ينقص ما عندنا. فيقول: بلى سلوني. فيقولون؟ نسألك رضاك. فيقول: رضاي، أحللكم دار كرامتي، فيفعل هذا بأهل كل درجة حتى ينتهي إلى مجلسه».\rهذا حديث مكذوب به على عمر بن عبد العزيز. وبعد كيف يثبت لله صفة بقول عمر بن عبد العزيز؟ وقال القاضي «أبو يعلى»: الآية تشهد لحديث عمر وهي قوله تعالى: {يَأْتِيَهُمُ اللهُ فِي ظُلَلٍ مِنَ الْغَمَامِ} [البقرة 210]. قلت: ولا يدري أن المعنى: يأتيهم الله بظلل من الغمام."], [68, "الحديث التاسع والثلاثون: "]], "pg": [67, 68]}, "493.46": {"x": [[68, "روي عن عائشة رضي الله عنها قالت: سئل رسول الله صلى الله عليه وسلم عن المقام المحمود قال: «وعدني ربي بالقعود على العرش».\rهذا حديث لا يصح عن رسول الله صلى الله عليه وسلم.\rقال ابن حامد: يجب الايمان بما ورد من المماسة والقرب من الحق لنبيه في إقعاده على العرش. قال: وقال ابن عمر: {وَإِنَّ لَهُ عِنْدَنَا لَزُلْفَى} [ص: 40]. قال: ذكر الله الدنو منه حتى يمس بعضه. وهذا كذب على ابن عمر ومن ذكر تبعيض الذات كفر بالاجماع.\r***\rالحديث الأربعون: "]], "pg": [68, 68]}, "493.47": {"x": [[68, "روى الدارقطني من حديث أبي اسحاق عن عبد الله بن خليفة عن عمر: أن أمرأة جاءت إلى رسول الله صلى الله عليه وسلم فقالت: ادع الله ان يدخلني الجنة فعظم الرب عز وجل فقال: «إن كرسيه وسع السموات والأرض، وإن له أطيطا كأطيط الرحل الجديد إذا ركب من ثقله».\rهذا حديث مختلف جدا، فتارة يروى عن عبد الله بن خليفة عن عمر عن رسول الله صلى الله عليه وسلم وتارة عن عمر موقوفا عليه. وقد رواه أبو إسحاق عن ابن خليفة عن ابن عمر قال: «إذا جلس تبارك وتعالى على الكرسي سمع له أطيط كأطيط الرحل». ورواه ابن جرير عن عبد الله بن خليفة قال: قال رسول الله صلى الله عليه وسلم: إن كرسيه وسع السموات والأرض وإنه ليقعد عليه فما"], [69, "يفضل منه مقدار أربع أصابع ثم قال بأصبعه فجمعها. وإن له أطيطا كأطيط الرحل إذا ركب من ثقله». وروى أبو بكر المروزي ان ابن خليفة قال: قال رسول الله صلى الله عليه وسلم: «الكرسي الذي يجلس عليه الرب ما يفضل منه إلا مقدار أربعة أصابع». قلت: هذا على ضد اللفظ الأول، وكل ذلك من تخليط الرواة وسوء الحفظ، والاليق فما يفضل منه مقدار أربع أصابع: والمعنى أنه قد ملاه بهيبته وعظمته، ويكون هذا ضرب مثل يقرب عظمة الخالق، وقول الرواة: «إذا قعد» و «إذا جلس» من تغييرهم أو من تعبيرهم بما يظنونه من المعنى، كما قال القائل: «ثم استوى على العرش» قعد، وإنما قلنا هذا لأن الخالق سبحانه وتعالى لا يجوز أن يوصف بالجلوس على شيء فيفضل من ذلك الشيء، لأن هذه صفة الأجسام.\r***\rالحديث الحادي والأربعون: "]], "pg": [68, 69]}, "493.48": {"x": [[69, "روى البخاري ومسلم في الصحيحين من حديث أبي سعيد عن رسول الله صلى الله عليه وسلم قال: «يقول الله عز وجل يوم القيامة: يا آدم فيقول: لبيك وسعديك. فينادي بصوت: إن الله يأمرك أن تخرج من ذريتك بعثا إلى النار».\rانفرد بلفظ «الصوت» حفص بن غياث وخالفه وكيع وجرير وغيرهما، فلم يذكروا الصوت. وسئل الإمام أحمد عن حفص قال: كان يخلط في حديثه.\rوفي الحديث الصحيح: «إذا تكلم الله بالوحي سمع أهل السماء للسماء صلصلة كجر السلسلة على الصفا». فرواه بعضهم بالمعنى الذي يظنه فقال: «سمع صوته أهل السماء». وفي حديث ابن مسعود: «إذا تكلم الله بالوحي سمع أهل السماء صلصلة كجر السلسلة على الصفا»."], [70, "وليس في الصحيح: سمع صوته أهل السماء.\r***\rالحديث الثاني والأربعون: "]], "pg": [69, 70]}, "493.49": {"x": [[70, "روى جابر رضي الله عنه عن النبي صلى الله عليه وسلم أنه قال: لما كلم الله موسى عليه السلام يوم الطور، كلمه بغير الكلام الذي به ناداه، فقال له: يا موسى إني كلمتك بقوة عشرة آلاف لسان ولي قوة الالسنة كلها، وأنا أقوى من ذلك فلما سمع رجع إلى بني اسرائيل قالوا: صف لنا كلام الرحمن, قال: لا أستطيع قالوا: قربه لنا قال: ألم تروا صوت الصواعق التي تقبل بأحلى كلام سمعتموه.\rهذا حديث لا يصح يرويه علي بن عاصم عن الفضل بن عيسى قال يحيى: كذاب ليس بشيء. وقال النسائي: علي بن عاصم متروك الحديث. وقال يزيد بن هارون: ما زلنا نعرفه بالكذب.\r***\rالحديث الثالث والأربعون: "]], "pg": [70, 70]}, "493.50": {"x": [[70, "روى القاضي «أبو يعلى» عن حسان بن عطية أنه قال: «الساجد يسجد على قدم الرحمن». قلت: هذا قول تابعي، وهو مثل المقرب من فضل الله تعالى، وأثبت القاضي «أبو يعلى» بهذا وصف قدم، وانه يسجد على قدم حقيقة لا على وجه المماسة.\r***"], [71, "الحديث الرابع والأربعون: "]], "pg": [70, 71]}, "493.51": {"x": [[71, "روى البخاري ومسلم في الصحيحين من حديث أبي موسى رضي الله عنه عن النبي صلى الله عليه وسلم أنه قال: «جنتان من فضة آنيتهما وما فيهما، وجنتان من ذهب آنيتهما وما فيهما، وليس بين القوم وبين أن ينظروا إلى ربهم إلا رداء الكبرياء على وجهه في جنة عدن».\rقلت: الرائي (هو الذي) في جنة عدن لا المرئي لأنه لا تحيط به الامكنة (سبحانه). قال القاضي «أبو يعلى»: ظاهر الحديث أنه المرئي في جنة عدن. وهذا هو التجسيم المحض، ورداء الكبرياء ما له من الكبرياء والعظمة، فكأنه إن منعهم فلعظمته، وإن شاء كشف لهم. وقد تكلمنا على الوجه في الآيات وقلنا المراد هو.\r***\rالحديث الخامس والأربعون: "]], "pg": [71, 71]}, "493.52": {"x": [[71, "روى البخاري ومسلم في الصحيحين من حديث أبي هريرة رضي الله عنه قال رسول الله صلى الله عليه وسلم: «لما قضى الله الخلق كتب في كتابه - فهو عنده (1) فوق العرش - إن رحمتي غلبت غضبي» وفي لفظ: «سبقت».\rقال القاضي «أبو يعلى»: ظاهر قوله عنده القرب من الذات. واعلم أن القرب من الحق لا يكون بمسافة وإنما ذلك\r__________\r(1) يقول العلامة العيني في شرح صحيح البخاري: والعندية ليست مكانية بل هو إشارة إلى كمال كونه مكنونا عن الخلق مرفوعا عن حيز إدراكهم. (ز)"], [72, "من صفة الاجسام، وقد قال تعالى: {مُسَوَّمَةً عِنْدَ رَبِّكَ} [هود: 83].\r***\rالحديث السادس والأربعون: "]], "pg": [71, 72]}, "493.53": {"x": [[72, "روي عن بعض التابعين أنه قال: «خلق الله آدم بيده، وكتب التوراة بيده وغرس الفردوس بيده».\rهذا حديث لا يثبت عن قائله وقد تكلمنا عليه عند قوله تعالى {لِمَا خَلَقْتُ بِيَدَيَّ} [ص: 75].\r***\rالحديث السابع والأربعون: "]], "pg": [72, 72]}, "493.54": {"x": [[72, "روى ابن عباس رضي الله عنهما عن النبي صلى الله عليه وسلم في قوله تعالى {وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ} [البقرة: 255] أنه قال: «كرسيه موضع قدميه، والعرش لا يقدر قدره».\rرواه جماعة من الاثبات فوقفوه على ابن عباس، ورفعه منهم شجاع بن مخلد (1) فعلم بمخالفته الكبار المتقنين أنه قد غلط.\rومعنى الحديث: أن الكرسي صغير بالاضافة إلى العرش كمقدار كرسي يكون عنده سرير قد وضع لقدمي القاعد على السرير. قال الضحاك: الكرسي الذي تجعل الملوك أرجلهم عليه، وقال القاضي «أبو يعلى»: القدم قدم الذات، وهي التي يضعها في النار.\r__________\r(1) يقول الحافظ ابن حجر في (تقريب التهذيب): شجاع بن مخلد الفلاس أبو الفضل البغوي نزيل بغداد صدوق وهم في حديث واحد رفعه وهو موقوف فذكره بسببه العقيلي في الضعفاء. (ز)"], [73, "الحديث الثامن والأربعون: "]], "pg": [72, 73]}, "493.55": {"x": [[73, "حديث العباس رضي الله عنه، عن رسول الله صلى الله عليه وسلم أنه قال: «فوق السماء السابعة بحر بين أعلاه وأسفله كما بين السماء والأرض، والله تعالى فوق ذلك».\rهذا حديث لا يصح تفرد به يحيى بن العلاء. قال الإمام أحمد: هو كذاب يضع الحديث.\rوقد تكلمنا في الفوق في قوله تعالى {وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ} [الأنعام: 18].\rقال القاضي «أبو يعلى»: المراد من الفوقية: استواء الذات على العرش، وهذا الكلام أصله التجسيم.\r***\rالحديث التاسع والأربعون: "]], "pg": [73, 73]}, "493.56": {"x": [[73, "روي في الصحيحين من حديث أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: «من تصدق بعدل تمرة من كسب طيب ولا يقبل الله إلا طيبا.، فإن الله يتقبلها بيمينه ثم يربيها لصاحبها كما يربي أحدكم فلوه حتى تكون مثل الجبل».\rوفي لفظ أخرجه مسلم: «فتربوا في كف الرحمن حتى تكون أعظم من الجبل».\rقال العلماء هذا خطاب للناس بما يعلمونه ويفهمونه من"], [74, "الأخذ والتربية والنمو، لما كان التناول باليد والقبض بالكف خاطبهم بما يعقلون، وإنما جرى ذكر اليمين لأنها مرصدة لما عز من الامور، ومعنى التربية: المضاعفة.\r***\rالحديث الخمسون: "]], "pg": [73, 74]}, "493.57": {"x": [[74, "روى البخاري ومسلم في الصحيحين من حديث أنس بن مالك رضي الله عنه عن النبي صلى الله عليه وسلم أنه ذكر الدجال فقال: «الا أنه أعور وإن ربكم ليس بأعور» (1).\rقال العلماء: إنما أراد تحقيق وصفه بأنه لا يجوز عليه النقص، والعور نقص ولم يرد إثبات جارحة، لأنه لا مدح في إثبات جارحة.\rبل كأنه قال: ربكم ليس بذي جوارح تتسلط عليه النقائص،\r__________\r(1) لفظ الحديث في صحيح البخاري «أن الله ليس بأعور، وأشار بيده إلى عينه وأن المسيح الدجال أعور عين اليمنى» وقد قال الحافظ ابن حجر: إن الإشارة إلى عينه صلى الله عليه وسلم إنما هي بالنسبة إلى عين الدجال فإنها كانت صحيحة مثل هذه ثم طرأ عليها العور لزيادة كذبه في دعوى الإلهية وهو أنه كان صحيح العين مثل هذه فطرأ عليها النقص ولم يستطع دفع ذلك عن نفسه أهـ.\rوقال الفخر الرازي في «أساس التقديس» عند الكلام على هذا الحديث: وأما هذا الخبر فمشكل لأن ظاهره يقتضي أن النبي صلى الله عليه وسلم أهر الفرق بين الإله تعالى وبين الدجال بكون الدجال أعور وكون الله تعالى ليس بأعور وذلك بعيد، وخبر الواحد إذا بلغ هذه الدرجة في ضعف المعنى وجب أن يعتقد أن الكلام كان مسبوقا بمقدمة لو ذكر لزال هذا الإشكال، أليس راوي هذا الحديث هو ابن عمر ثم إن المشهور أن ابن عمر لما روى حديث «إن الميت ليعذب ببكاء أهله» طعنت عائشة رضي الله عنها فيه وذكرت أن هذا الكلام من الرسول كان مسبوقا بكلام آخر واحتجت على ذلك بقوله تعالى {وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى} [الأنعام: 164] لو حكى لزال هذا الإشكال فكذا هاهنا أنه من البعيد صدرور مثل هذا الكلام من الرسول أهـ."], [75, "وهذا مثل نفي الولد عنه لأنه يستحيل عليه التجزئ، ولو كانت الاشارة إلى صورة كاملة، لم يكن في ذلك دليل على الالوهية ولا القدم فإن الكامل في الصورة كثير.\r***\rالحديث الحادي والخمسون: "]], "pg": [74, 75]}, "493.58": {"x": [[75, "روى البخاري في أفراده من حديث أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: يقول الله عز وجل: «ما يزال عبدي يتقرب إلي بالنوافل حتى أحبه، فإذا أحببته كنت سمعه الذي يسمع به وبصره الذي يبصره به ويده التي يبطش بها ورجله التي يمشي بها، وما ترددت عن شيء أنا فاعله ترددي عن نفس المؤمن يكره الموت وأكره مساءته».\rقوله: «كنت سمعه، وبصره» فهو «مثل» وله ثلاثة أوجه:\rأحدها: كنت كسمعه وبصره فهو يحب طاعتي. كما يحب هذه الجوارح.\rوالثاني: أن جوارحه مشغولة بي، فلا يصغي إلى غير ما يرضيني ولا يبصر إلا عن أمري.\rوالثالث: أني أحصل له مقاصده كما ينالها بسمعه وبصره ويديه اللواتي تعينه على عدوه، وأما التردد فخطاب لنا بما نعقل.\r***"], [76, "الحديث الثاني والخمسون: "]], "pg": [75, 76]}, "493.59": {"x": [[76, "روى جبير بن مطعم قال: أتى رسول الله صلى الله عليه وسلم أعرابي فقال: يا رسول الله: جهدت الانفس وجاعت العيال، ونهكت الاموال، وهلكت الانعام فاستسق الله لنا، فانا نستشفع بك على الله ونستشفع بالله عليك، فقال رسول الله صلى الله عليه وسلم ويحك: أتدري ما تقول؟؟ وسبح رسول الله صلى الله عليه وسلم، فما زال يسبح حتى عرف ذلك في وجه أصحابه فقال: إنه لا يستشفع بالله على أحد من خلقه. شأن الله أعظم من ذلك: ويحك أتدري ما الله؟ إن عرشه على سمواته هكذا، وقال باصابعه مثل القبة، وإنه ليئظ به كأطيط الرحل بالراكب.\rومعنى قوله: أتدري ما الله «أتدري ما الله» أي أتدري ما عظمة الله وجلاله, ومعنى يئط به: أي يعجز عن جلاله وعظمته، إذ كان معلوما أن أطيط الرحل بالراكب معلوما لقوة ما فوقه، أو لعجزه عن احتماله، فقرب بهذا النوع من التمثيل عنده معنى عظمة الله وجلاله ليعلمه أن الموصوف بعلو الشأن لا يجعل شفيعا لمن هو دونه في القدر, وقد ذكرنا فيما تقدم عن القاضي «أبي يعلى» أنه قال: «يئط من ثقل الذات» وهذا صريح في التجسيم.\r***\rالحديث الثالث والخمسون: "]], "pg": [76, 76]}, "493.60": {"x": [[76, "روى أبو هريرة رضي الله عنه عن النبي صلى الله عليه وسلم أنه «قرأ: {إِنَّ اللهَ كَانَ سَمِيعًا بَصِيرًا} [النساء: 58]. فوضع إصبع الدعاء وإبهامه على عينيه وأذنيه»."], [77, "قال العلماء: أراد بهذا تحقيق السمع والبصر لله تعالى، فأشار إلى الجارحتين اللتين هما محل السمع والبصر، لا أن لله سبحانه جارحة.\r***\rالحديث الرابع والخمسون: "]], "pg": [76, 77]}, "493.61": {"x": [[77, "روى أبو الدرداء رضي الله عنه عن النبي صلى الله عليه وسلم أنه قال: «إن الله عز وجل ينزل في ثلاث ساعات يبقين من الليل، فيفتح الذكر في الساعة الأولى، فيمحو ما يشاء ويثبت، ثم ينزل في الساعة الثانية إلى جنة عدن وهي داره التي لم يسكنها غيره، وهي مسكنه، ثم يقول طوبى لمن يسكنك ثم ينزل في الساعة الثالثة إلى السماء الدنيا بروحه وملائكته فيقول: قومي بعزتي».\rهذا الحديث يرويه زيادة الأنصاري، قال البخاري، هو منكر الحديث وذكر له أهل الحديث هذا الحديث وقال أبو حاتم بن حبان يروي المناكير عن المشاهير، واستحق الترك. ونقول على تقدير الصحة إنها مضافة إليه كما أضيف البيت إليه يقال: هذا بيته وهذا مسكنه، وإنما قلنا هذا لأن السكنى مستحيلة في حقه.\r***\rالحديث الخامس والخمسون: "]], "pg": [77, 77]}, "493.62": {"x": [[77, "روى أبو أمامة عن رسول الله صلى الله عليه وسلم"], [78, "أنه قال: «وعدني ربي أن يدخل الجنة من أمتي سبعين ألفا وثلاث حثيات من حثياته».\rالحثية ملء الكف. والمراد التقريب بما يعقل لا حقيقة الحثية.\r***\rالحديث السادس والخمسون: "]], "pg": [77, 78]}, "493.63": {"x": [[78, "روى أبوأمامه عن رسول الله صلى الله عليه وسلم أنه قال: «إن الله يجلس يوم القيامة على القنطرة الوسطى بين الجنة والنار».\rيرويه عثمان بن أبي عاتكة وقال يحيى: ليس بشيء.\r***\rالحديث السابع والخمسون: "]], "pg": [78, 78]}, "493.64": {"x": [[78, "روى القاضي «أبو يعلى» عن محمد بن كعب قال «إن الناس إذا سمعوا القرآن من في الرحمن كأنهم لم يسمعوه قط».\rقال القاضي «أبو يعلى»: ولا يمتنع أن يطلق الفم عليه.\rقلت: وآعجبا يعني «في» الرحمن فمه، فيثبت لله صفة بقول تابعي لا تصح الرواية عنه. هذا من أقبح الاشياء.\rفأما الحديث الذي سبق عن أبي أمامه عن رسول الله صلى الله عليه وسلم أنه قال: «ما تقرب إلي بمثل ما خرج مني». فالمعنى: ظهر،"], [79, "عنه ولا يجوز أن يظن أنه كخروج جسم من جسم.\r***\rالحديث الثامن والخمسون: "]], "pg": [78, 79]}, "493.65": {"x": [[79, "روينا عن سهل بن سعد عن النبي صلى الله عليه وسلم قال: «دون الله سبعون ألف حجاب من نور وظلمة وما تسمع من نفس شيئا من حس تلك الحجب إلا زهقت»\rهذا حديث لا أصل له.\r***\rالحديث التاسع والخمسون: "]], "pg": [79, 79]}, "493.66": {"x": [[79, "رواه أنس أن النبي صلى الله عليه وسلم قال «إن لله للوحا، أحد وجهيه درة والآخر ياقوته، قلمه النور، فبه يخلق وبه يرزق وبه يحيي وبه يميت، ويعز ويذل، ويفعل ما يشاء في يوم وليلة».\rهذا الحديث موضوع، يرويه محمد بن عثمان وهو متروك.\r***\rالحديث الستون: "]], "pg": [79, 79]}, "493.67": {"x": [[79, "روى جابر رضي الله عنه عن النبي صلى الله عليه وسلم أنه قال: «إذا رأيتم الريح فلا تسبوها فإنها من نفس الرحمن، تأتي بالرحمة وتأتي بالعذاب فاسألوا الله خيرها واستعيذوا بالله من شرها»."], [80, "النفس بمعنى التنفيس عن المكروب (1)، ومثله ما رواه أبو هريرة رضي الله عنه عن النبي صلى الله عليه وسلم أنه قال: «إني لاجد نفس ربكم من قبل اليمن» يعني تنفيسه عن المكروب بنصرة أهل المدينة إياي والمدينة من جانب اليمن، وهذا شيء لا يختلف فيه المسلمون.\rوقال ابن حامد: رأيت بعض أصحابنا يثبتون لله وصفا في ذاته بأنه يتنفس. قال وقالوا الرياح الهابة مثل الرياح العاصفة، والعقيم والجنوب والشمال والصبا والدبور مخلوقة، إلا ريحا من صفاته هي ذات نسيم حياتي، وهي من نفس الرحمن.\rقلت: على من يعتقد هذا اللعنة، لانه يثبت جسدا مخلوقا وما هؤلاء بمسلمين.\rقال المصنف: ولما علم بكتابي هذا جماعة من الجهال لم يعجبهم، لانهم ألفوا كلام رؤسائهم المجسمة، فقالوا: ليس هذا المذهب.\rقلت: ليس بمذهبكم ولا مذهب من قلدتم من أشياخكم، فقد نزهت مذهب الإمام أحمد رحمه الله، ونفيت عنه كذب المنقولات، وهذيان المقولات غير مقلد لهم فيما اعتقدوه وكيف أعتقد بهرجا وأنا أنتقده. قلت:\r__________\r(1) يقول الزمخشري في أساس البلاغة: ومالي نفس أي فرج. وقال ابن قتيبة: وقد فرج الله عن نبيه صلى الله عليه وسلم بالريح يوم الأحزاب، قال تعالى {فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا وَجُنُودًا لَمْ تَرَوْهَا} [الأحزاب: 9]."], [81, "سبقت بحمد الله من كان من قبلي ... فقل للذي يرجو لحاقي على مهل\rوإنكم لو تنقصون عتابكم ... لعز على التفتيش أن تجدوا مثلي\rثم قصيدة مطولة "]], "pg": [79, 81]}, "493.68": {"x": [[81, "وهي:\rحمدت إلهي كيف لا وله الفضل ... كما قد تولاني فذلت لي السبل\rوأخرجني من بين أهلي مفهما ... وعلمني علما به قيمتي تغلو\rوحركني للمكرمات أحوزها ... فهمة نفسي دائما أبدا تعلو\rوألهمني بالعلم حتى ملكته ... فصار مرير الصبر عند فمي يحلو\rوقد زاد عشقي للعلوم فأصبحت ... كتمثال ليلى عند قيس فما يسلو\rفما من علوم بثها الله في الورى ... إلى خلقه إلا ولي معها وصل\rوصنفت ما قد صنف الناس جنسه ... فيا قاصدي الانصاف لي ميزوا وابلوا\rولي من بديهات الكلام عجائب ... تكر عليهم كلما طولت تحلو\rوقد قادني علمي إلى الزهد في الدنا ... وما جمعا إلا لعبد له فضل\rنعم وتقاة الله أشرف خلقه ... ولا خير في قول إذا ضيع الفعل\rقنوعي بما يكفي يقيني من الأذى ... وبعد يقيني بالمقادير لا ذل\rوأحسن من علم ترامي بأهله ... إلي مين مخلوق يماثله الجهل\rوأسكن قلبي حب كل محقق ... يعشق كما قد تعشق الأعين النجل"], [82, "وبغداد داري ليس يغبن أهلها ... وما جهم إلا لمن ما له شكل و\rكل البلاد أشحنتها فضائلي ... أقر بفضلي الدين والحزن والسهل\rوذكري وراء النهر بالفضل وافر ... وفي المغرب الاقصى وما بلغت ابل\r***\rولما نظرت المذاهب كلها ... طلبت الأسد في الصواب وما أغلو\rفألفيت عند السير قول ابن حنبل ... يزيد على المذاهب بل يعلو\rوكل الذي قد قاله فشيد ... بنقل صحيح والحديث هو الأصل\rوكان بنقل العلم أعرف من روى ... بقوم من السادات ما شانه عضل\r***\rومذهبه أن لا يشبه ربه ... ويتبع في التسليم من قد مضى قبل\rفقام له الحساد من كل جانب ... . فقام على رجل الثبات وهم زلوا\rوكان له أتباع صدق تتابعوا ... فكم أرشدوا نحو الهدى وكم دلوا\rوجاءك قوم يدعون تمذهبا ... بمذهبه ما كل فرع له أصل\rفلا في فروع يثبتون لنصره ... وعندهم من فهم ما قاله شغل\rإذا ناظروا قاموا مقام مقاتل ... فواعجبا والقوم كلهم عزل\rقياسهم طردا إذا ما صدروا به ... وهم من علوم النقل أجمعها عطل"], [83, "إذا لم يكن في النقل صاحب فطنة ... تشابهت الحياة وانقطع الحبل\rومالوا إلى التشبيه أخذا بصورة ... الذي نقلوه في الصفات وهم غفل\rوقالوا الذي قلناه مذهب أحمد ... فمال إلى تصديقهم من به جهل\rوصار الأعادي قائلين ... لكنا مشبهة قد ضرنا الصحب والخل\rفقد فضحوا ذاك الإمام بجهلهم ... ومذهبه التنزيه لكن هم اختلوا\rلعمري لقد أدركت منهم مشايخا ... وأكثر من أدركتهم ما له عقل\rوما زلت أجلوا عندهم كل خلة ... من الاعتقاد الرذل كي يجمع الشمل\rتسموا بألقاب ولا علم عندهم ... فوائدهم لا حرم فيها ولا حل\rموائدهم لا يلحق الخل بقلها ... وإن شئت لا خل لديهم ولا بقل\r***\rوأكثر حساد لنا أهل مذهبي ... فلو قدروا أفتوا بأن دمي حل\rتمنوا بجهل أن تزل بي النعلي ... ولم تمش في مجد بمثلي لهم رجل\rومنذ مضى شيخ الجماعة أحمد ... إلى الآن لم يوجد لعالمكم مثل\rلقد بات عندي ألف ألف يقدموا ... سحابة وغطى كلهم صيب وبل\rوروضات علمي كلها تمرح الجنا ... وبستانهم إذا ما تأملته أثل\rوكيف ترى تبري الحسود وداؤه ... إذا سئل الطب الخبير به يسلوا\rتفرد بالبغض القبيح مخالف ... أليس اجتماع الناس لي شاهد عدل\r***"], [85, "تم الكتاب دفع شبه التشبيه للإمام ابن الجوزي\rجاء في آخر «مجلس في نفي التشبيه من أمالي الحافظ أبي القاسم علي بن الحسن بن هبة الله الشافعي»: أنشدنا أبو محمد بن الحسن منصور المؤمل لنفسه:\rللهُ أكبرُ أن يكون لذاتِهِ ... كيفيّةٌ كذواتِ مخلوقاتِهِ\rأوْ أنْ تُقاسَ صفاتُنا في كلّ ما ... نأتيهِ من أفعالِنا بصفاتِهِ\rتبًا لذى سفه يقول بأنه ... جسم وأن سماتنا كسماته\rلَبَديعُ صَنعتِهِ عليه شواهدٌ ... تبدو على صفحاتِ مصنوعاتِهِ\rذر الأنام بقدرة أزلية ... وأراده فيهم لتقديراته\rورأى بعين العلم ما تأتى به ... لمحات أعينهم وما لم تاته\r***"], [86, "الفهرس\r"]], "pg": [81, 86]}, "493.69": {"x": [[86, "الموضوع ... الصفحة\rالمقدمة ... 1\rبعض مصنفات ابن الجوزي الدينية ... 2\rالمردود عليه في هذه العجالة ... 4\rبعض الصفات التي حملها مشبه على ظاهره ... 5\rفصل في الأغلاط التي وقع فيها المردود عليهم ... 7\rباب ما جاء في القرآن العظيم من آيات الصفات ... 10\rالحافظ أبو بكر بن خزيمه وإنه ممن سقطوا في هوة التشبيه ... 11\rتمسك المشبه بظاهر الآيات التي توهن تعيين الجهة وتأويلهم ما يخالف ذلك بزعمهم ... 21\rباب ذكر الأحاديث التي سموها أخبار الصفات ... 26\rخطأ ابن قتيبه في قوله: لله صورة لا كالصور فخلق آدم عليها ... 29"], [87, "تقسيم الناس في أخبار الصفات على ثلاثة مراتب ... 57\rما اختاره ابن دقيق العيد في التأويل ... 59\rخاتمة الكتاب، وذكر بيتين للمصنف يحمد الله بهما قصيدة مطولة يبين فيها المصنف عشقه للعلوم واختياره لمذهب الإمان أحمد ... 79"]], "pg": [86, 87]}}, "units": {"90": {"tit": "مقدمة الطبعة الأولى", "lvl": 1, "pg": [3, 4]}, "91": {"tit": "المقدمة", "lvl": 1, "pg": [4, 9]}, "96": {"tit": "فصل: في الأغلاط التي وقع فيها المردود عليهم", "lvl": 1, "pg": [9, 12]}, "104": {"tit": "باب: ما جاء في القرآن العظيم من آيات الصفات", "lvl": 1, "pg": [12, 13]}, "105": {"tit": "الحافظ أبو بكر بن خزيمه وإنه ممن سقطوا في هوة التشبيه", "lvl": 2, "pg": [13, 21]}, "120": {"tit": "تمسك المشبه بظاهر الآيات التي توهن تعيين الجهة وتأويلهم ما يخالف ذلك بزعمهم", "lvl": 2, "pg": [21, 28]}, "144": {"tit": "باب ذكر الأحاديث التي سموها أخبار الصفات", "lvl": 1, "pg": [28, 31]}, "147": {"tit": "الحديث الثاني", "lvl": 2, "pg": [31, 33]}, "149": {"tit": "الحديث الثالث", "lvl": 2, "pg": [33, 34]}, "150": {"tit": "الحديث الرابع", "lvl": 2, "pg": [34, 35]}, "151": {"tit": "الحديث الخامس", "lvl": 2, "pg": [35, 37]}, "153": {"tit": "الحديث السادس", "lvl": 2, "pg": [37, 38]}, "154": {"tit": "الحديث السابع", "lvl": 2, "pg": [38, 39]}, "155": {"tit": "الحديث التاسع", "lvl": 2, "pg": [39, 41]}, "157": {"tit": "الحديث العاشر", "lvl": 2, "pg": [41, 43]}, "159": {"tit": "الحديث الثاني عشر", "lvl": 2, "pg": [43, 44]}, "160": {"tit": "الحديث الثالث عشر", "lvl": 2, "pg": [44, 45]}, "161": {"tit": "الحديث الرابع عشر", "lvl": 2, "pg": [45, 46]}, "162": {"tit": "الحديث الخامس عشر", "lvl": 2, "pg": [46, 47]}, "163": {"tit": "الحديث السادس عشر", "lvl": 2, "pg": [47, 48]}, "164": {"tit": "الحديث الثامن عشر", "lvl": 2, "pg": [48, 49]}, "165": {"tit": "الحديث التاسع عشر", "lvl": 2, "pg": [49, 51]}, "211": {"tit": "الحديث العشرين", "lvl": 2, "pg": [51, 52]}, "212": {"tit": "الحديث الثاني والعشرون", "lvl": 2, "pg": [52, 53]}, "213": {"tit": "الحديث الثالث والعشرون", "lvl": 2, "pg": [53, 54]}, "214": {"tit": "الحديث الرابع والعشرون", "lvl": 2, "pg": [54, 55]}, "215": {"tit": "الحديث الخامس والعشرون", "lvl": 2, "pg": [55, 56]}, "221": {"tit": "الحديث السابع والعشرون", "lvl": 2, "pg": [56, 57]}, "222": {"tit": "الحديث الثامن والعشرون", "lvl": 2, "pg": [57, 58]}, "223": {"tit": "الحديث الحادي والثلاثون", "lvl": 2, "pg": [58, 62]}, "238": {"tit": "الحديث الثاني والثلاثون", "lvl": 2, "pg": [62, 63]}, "239": {"tit": "الحديث الثالث والثلاثون", "lvl": 2, "pg": [63, 65]}, "241": {"tit": "الحديث الخامس والثلاثون", "lvl": 2, "pg": [65, 66]}, "242": {"tit": "الحديث السادس والثلاثون", "lvl": 2, "pg": [66, 67]}, "243": {"tit": "الحديث الثامن والثلاثون", "lvl": 2, "pg": [67, 68]}, "244": {"tit": "التاسع والثلاثون", "lvl": 2, "pg": [68, 69]}, "245": {"tit": "الحديث الحادي والأربعون", "lvl": 2, "pg": [69, 70]}, "258": {"tit": "الحديث الثاني والأربعون", "lvl": 2, "pg": [70, 71]}, "259": {"tit": "الحديث الرابع والأربعون", "lvl": 2, "pg": [71, 72]}, "260": {"tit": "الحديث السادس والأربعون", "lvl": 2, "pg": [72, 73]}, "262": {"tit": "الحديث الثامن والأربعون", "lvl": 2, "pg": [73, 74]}, "269": {"tit": "الحديث الخمسون", "lvl": 2, "pg": [74, 75]}, "270": {"tit": "الحديث الحادي والخمسون", "lvl": 2, "pg": [75, 76]}, "271": {"tit": "الحديث الثاني والخمسون", "lvl": 2, "pg": [76, 77]}, "272": {"tit": "الحديث الرابع والخمسون", "lvl": 2, "pg": [77, 78]}, "282": {"tit": "الحديث السادس والخمسون", "lvl": 2, "pg": [78, 79]}, "283": {"tit": "الحديث الثامن والخمسون", "lvl": 2, "pg": [79, 81]}, "285": {"tit": "قصيدة مطولة", "lvl": 1, "pg": [81, 86]}, "290": {"tit": "الفهرس", "lvl": 1, "pg": [86, 87]}}};
